try{data=JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{data=null}
if(!data||!Array.isArray(data.people)||!Array.isArray(data.memories))data={people:structuredClone(peopleSeed),memories:structuredClone(memorySeed),sources:structuredClone(sourceSeed),favorites:[],followed:[],activities:[],notes:[],ocrDone:false,linked:false};
let state={route:'home',person:'p3',tab:'details',treeView:'landscape',generations:4,zoom:1,panX:0,panY:0,selected:null,memoryFilter:'all',memoryQuery:'',studioMode:'ocr',ocrStage:data.ocrDone?3:1,ocrPreview:null,interviewStep:0,chat:[],descExpanded:true};
const person=id=>data.people.find(p=>p.id===id)||data.people[0];
const avatar=(p,size='')=>`<span class="avatar ${p.sex==='F'?'female':''} ${size}">${esc(p.name.slice(-2,-1)||p.name[0])}</span>`;
const lifespan=p=>`${esc(p.birth||'生年待补')} — ${p.death?esc(p.death):'在世'}`;
const pID=p=>`JX-${p.id.replace('p','').padStart(4,'0')}`;
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(data));return true}catch{toast('浏览器存储空间不足，请导出资料后再试');return false}}
function logActivity(text){data.activities.unshift({text,time:new Date().toLocaleString('zh-CN',{hour12:false})});data.activities=data.activities.slice(0,12);save()}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3400)}
function footer(){return `<footer class="page-footer"><span>家续 · 数字族谱与家庭记忆 <span style="padding:0 9px">/</span> 保存来处，继续生活</span><span>演示数据仅保存在当前浏览器 <a href="#" data-action="about" style="margin-left:18px">关于本次体验</a></span></footer>`}
function button(text,action,cls='btn',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`}
function render(){
 document.body.classList.toggle('tree-mode',state.route==='tree');
 $$('.main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===(state.route==='person'?'tree':state.route)));
 const views={home:homeView,tree:treeView,person:profileView,memories:memoriesView,roots:rootsView,studio:studioView};
 $('#main').innerHTML=(views[state.route]||homeView)(); fillIcons();
 if(state.route==='tree')bindTreeDrag();
}
function router(){const parts=location.hash.replace(/^#/,'').split('/');state.route=parts[0]||'home';if(state.route==='person'){state.person=parts[1]||'p3';state.tab=parts[2]||'details'}closeDrawer();closeModal();render();window.scrollTo(0,0)}
function go(route){if(location.hash==='#'+route){router()}else location.hash=route}
function homeView(){
 const activities=data.activities.length?data.activities.slice(0,3):[{text:'林建民补充了一封家书',time:'昨天 16:30'},{text:'林知远关联了 2 条人物来源',time:'10月23日'},{text:'陈淑华分享了一段年节往事',time:'10月21日'}];
 return `<div class="page home-page"><div class="welcome-line"><strong>上午好，知远。很高兴与你一起续写家里的故事。</strong><span>林氏家庭空间 ${icon('lock')}</span></div>
 <div class="home-grid"><div><section class="hero"><div class="hero-copy"><div class="eyebrow">EVERY FAMILY HAS A STORY</div><h1>每一个名字背后，<br>都有值得留下的故事。</h1><p>从你和家人开始，连接几代人的记忆，<br>让来处有迹可循，让故事有人接续。</p><a class="btn btn-primary" href="#tree">探索我的家族树 ${icon('arrow-right')}</a></div><div class="hero-art"><div class="hero-seal">家 · 续</div><img class="hero-photo" src="assets/courtyard.svg" alt="闽南古厝原创示意插画"><img class="hero-letter" src="assets/letter.svg" alt="家书原创示意文稿"></div></section>
 <div class="quick-actions">${[['image','上传一段记忆','照片、家书与故事','upload-memory'],['mic','听长辈讲故事','从一个问题开始','interview-route'],['users','邀请家人加入','让记忆一起生长','invite']].map(([ic,t,s,a])=>`<button class="quick-action" data-action="${a}"><span class="action-icon">${icon(ic)}</span><span><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div></div>
 <aside class="panel family-panel"><div class="actions" style="justify-content:space-between"><span class="tag">家庭空间</span>${icon('shield')}</div><div class="family-name">林氏 · 我们的家</div><span class="small muted">福建南安 · 台湾台南 · 厦门</span><div class="avatar-stack">${['林','陈','沈','黄'].map((x,i)=>`<span class="mini-avatar" style="background:${['#e4ebd7','#f0e5dd','#e4e8f0','#f1ecd9'][i]}">${x}</span>`).join('')}<span>4 位家人共同整理</span></div><div class="family-summary"><div><strong>${data.people.length}</strong><span>位家人</span></div><div><strong>4</strong><span>代关系</span></div><div><strong>${data.memories.length}</strong><span>段记忆</span></div></div>${button('查看家庭成员 '+icon('arrow-right'),'members','btn btn-soft')}<div class="small muted" style="font-size:10px;padding-bottom:20px">${icon('lock')} 在世人物与家庭记忆仅授权家人可见</div></aside></div>
 <div class="home-lower"><div><div class="section-heading"><h2>一点补充，让家谱更完整</h2><a class="text-link" href="#studio">查看整理助手 ${icon('arrow-right')}</a></div><div class="tasks"><article class="task"><span class="task-icon">${icon('book')}</span><div><div class="task-title">一页老谱，等待你来确认</div><p>${data.ocrDone?'你已完成演示谱页核对，来源已关联到祖父档案。':'林文海的名讳与出生地已找到线索，核对原图后再收录。'}</p>${button(data.ocrDone?'查看整理结果':'对照谱页','ocr-route','text-link')}</div></article><article class="task"><span class="task-icon">${icon('pin')}</span><div><div class="task-title">沿着家书，找回家族的来处</div><p>南安与台南两地谱本有一条待核线索，看看名字背后的联系。</p><a href="#roots" class="text-link">查看闽台线索 ${icon('arrow-right')}</a></div></article></div>
 <div class="section-heading"><h2>家人留下的记忆</h2><a class="text-link" href="#memories">全部记忆 ${icon('arrow-right')}</a></div><div class="memory-teaser">${data.memories.slice(0,3).map(m=>`<article class="memory-mini" data-action="memory" data-id="${m.id}" tabindex="0" role="button" aria-label="查看${esc(m.title)}">${m.image?`<img src="${m.image}" alt="${esc(m.title)}">`:`<div style="height:132px">${audioArt()}</div>`}<div class="memory-mini-body"><h4>${esc(m.title)}</h4><p>${esc(m.year)} · ${esc(person(m.person).name)}</p></div></article>`).join('')}</div></div>
 <aside><div><div class="section-heading"><h2 style="font-size:16px">家里的新动态</h2>${icon('clock')}</div><div class="panel" style="padding-top:23px"><div class="activity-list">${activities.map(a=>`<div class="activity">${esc(a.text)}<small>${esc(a.time)}</small></div>`).join('')}</div></div></div><div style="margin-top:24px" class="roots-mini"><div class="eyebrow" style="font-size:9px">ROOTS ACROSS THE STRAIT</div><h3>山海相望，<br>家脉相连。</h3><p>从一处旧地名、一封家书开始，<br>一步一步核对两地家族的联结。</p><a href="#roots" class="text-link">走近家族的来处 ${icon('arrow-right')}</a></div></aside></div>${footer()}</div>`;
}
function nodeHTML(p,x,y,compact=false){return `<button class="person-node ${p.sex==='F'?'female':''} ${state.selected===p.id?'selected':''}" style="left:${x}px;top:${y}px;${compact?'min-height:61px;padding:9px 12px;':''}" data-action="person-drawer" data-id="${p.id}" aria-label="查看${esc(p.name)}人物摘要">${avatar(p)}<span class="node-info"><strong>${esc(p.name)} ${p.style?'<span class="tiny muted">承远</span>':''}</strong><small>${lifespan(p)}</small><span class="node-id">${pID(p)}</span></span>${p.death?`<span class="node-badge">${icon('file')}</span>`:`<span class="node-badge">${icon('lock')}</span>`}</button>`}
function landscape(){let nodes=[['p0',42,300,false],['p1',349,173,false],['p2',349,429,false],['p3',656,78,false],['p4',656,232,false],['p5',656,389,false],['p6',656,543,false]];if(state.generations===4)nodes.push(...['p7','p8','p9','p10','p11','p12','p13','p14'].map((id,i)=>[id,963,42+i*75,true]));let paths='';for(const [id,x,y,c]of nodes){const p=person(id);for(const par of [p.father,p.mother]){const dst=nodes.find(n=>n[0]===par);if(dst){let sy=y+(c?30:42),ey=dst[2]+(dst[3]?30:42);paths+=`<path d="M${x+214} ${sy}H${x+260}Q${x+267} ${sy} ${x+267} ${sy+(ey>sy?7:-7)}V${ey+(ey>sy?-7:7)}Q${x+267} ${ey} ${x+274} ${ey}H${dst[1]}"/>`}}}return `<div id="tree-canvas" class="tree-canvas" style="transform:translate(${state.panX}px,${state.panY}px) scale(${state.zoom})"><svg class="tree-lines" viewBox="0 0 1320 650">${paths}</svg>${[['本人',42],['父母',349],['祖父母 / 外祖父母',656],['曾祖辈',963]].filter((x,i)=>i<state.generations).map(([t,x])=>`<span class="generation-label" style="left:${x}px">${t}</span>`).join('')}${nodes.map(([id,x,y,c])=>nodeHTML(person(id),x,y,c)).join('')}</div>`}
function fanChart(){const polar=(r,deg)=>[400+r*Math.cos(deg*Math.PI/180),455+r*Math.sin(deg*Math.PI/180)];const wedge=(r1,r2,a,b)=>{let p1=polar(r2,a),p2=polar(r2,b),p3=polar(r1,b),p4=polar(r1,a);return `M${p1}A${r2} ${r2} 0 0 1 ${p2}L${p3}A${r1} ${r1} 0 0 0 ${p4}Z`};let out='';const ids=[['p1','p2'],['p3','p4','p5','p6'],['p7','p8','p9','p10','p11','p12','p13','p14']];ids.slice(0,state.generations-1).forEach((row,l)=>row.forEach((id,i)=>{let a=-180+i*180/row.length,b=a+180/row.length,xy=polar(104+l*92,(a+b)/2);out+=`<g role="button" tabindex="0" aria-label="查看${esc(person(id).name)}" data-action="person-drawer" data-id="${id}"><path d="${wedge(58+l*92,149+l*92,a,b)}" fill="${['#dfeacb','#cbdcb1','#e6dfcb','#d4e2d4'][i%4]}"/><text x="${xy[0]}" y="${xy[1]}" text-anchor="middle">${esc(person(id).name)}</text><text x="${xy[0]}" y="${xy[1]+18}" text-anchor="middle" style="font-size:9px;opacity:.65">${esc(person(id).birth)}</text></g>`}));return `<div class="fan-wrap"><svg class="fan-svg" viewBox="0 0 800 520" aria-label="四代祖先扇形图">${out}<circle cx="400" cy="455" r="54" fill="#7b9856" data-action="person-drawer" data-id="p0" style="cursor:pointer"/><text x="400" y="452" text-anchor="middle" style="fill:white;font-size:15px">林知远</text><text x="400" y="474" text-anchor="middle" style="fill:#ecf1df;font-size:9px">从我开始 · 1991</text></svg></div>`}
function descendants(){const rows=[['p7',0,'曾祖父'],['p3',24,'儿子'],['p1',48,'孙子'],['p0',72,'曾孙'],['p16',96,'玄孙女']];return `<div class="descendants"><div class="actions" style="justify-content:space-between;margin-bottom:16px"><h3 style="margin:0">林宗源的后代</h3>${button(state.descExpanded?'折叠后代':'展开后代','toggle-desc','text-link')}</div>${rows.filter((x,i)=>state.descExpanded||i===0).map(([id,indent,rel])=>`<div class="descendant-row" style="padding-left:${15+indent}px" data-action="person-drawer" data-id="${id}" role="button" tabindex="0">${avatar(person(id))}<span><strong>${esc(person(id).name)}</strong><small class="muted" style="display:block;font-size:10px">${lifespan(person(id))}</small></span><span class="relationship">${rel}</span>${icon('chevron-right')}</div>`).join('')}<p class="small muted" style="font-size:10px;margin:17px 0 0">展示已记录的后代支系，未录入的关系可继续补充。</p></div>`}
function treeView(){return `<div class="tree-page"><div class="tree-toolbar"><div class="tree-title">${icon('tree')}<div><strong>林氏 · 家族树</strong><small>以林知远为中心 · 福建南安—台湾台南</small></div>${button(icon('chevron-down'),'members','icon-btn','aria-label="查看家族成员"')}</div><div class="view-switch" aria-label="家族树视图">${[['landscape','tree','横向树'],['fan','fan','扇形图'],['descendants','list','后代图']].map(([v,i,t])=>`<button data-action="tree-view" data-view="${v}" class="${state.treeView===v?'active':''}" aria-pressed="${state.treeView===v}">${icon(i)}${t}</button>`).join('')}</div><div class="tree-actions"><select id="generations" aria-label="显示代数"><option value="4" ${state.generations===4?'selected':''}>显示 4 代</option><option value="3" ${state.generations===3?'selected':''}>显示 3 代</option></select>${button(icon('plus')+' 添加人物','add-person','btn btn-primary btn-sm')}</div></div><div class="tree-subbar"><div class="actions">${button(icon('user')+' 回到本人','tree-reset','text-link')}${button(icon('search')+' 查找人物','search','text-link')}${button(icon('download')+' 导出家谱','export','text-link')}</div><div class="legend"><span><i></i>男性</span><span><i class="female-dot"></i>女性</span><span>${icon('lock')} 在世人物受限可见</span></div></div><div class="tree-workspace" id="tree-workspace">${state.treeView==='landscape'?landscape():state.treeView==='fan'?fanChart():descendants()}${state.treeView==='landscape'?`<div class="tree-controls">${button(icon('plus'),'zoom-in','','aria-label="放大家族树"')}${button(icon('minus'),'zoom-out','','aria-label="缩小家族树"')}<button class="zoom-text" data-action="tree-reset" aria-label="重置缩放">${Math.round(state.zoom*100)}%</button>${button(icon('focus'),'tree-reset','','aria-label="居中家族树"')}</div><div class="tree-hint">拖动空白区域移动 · 点击人物查看资料 · Ctrl + 滚轮缩放</div>`:''}</div></div>`}
function bindTreeDrag(){const work=$('#tree-workspace'),can=$('#tree-canvas');if(!can)return;let down=false,start,origin,moved=false;work.addEventListener('pointerdown',e=>{if(e.target.closest('button,a,select'))return;down=true;moved=false;start=[e.clientX,e.clientY];origin=[state.panX,state.panY];can.classList.add('dragging');work.setPointerCapture(e.pointerId)});work.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-start[0],dy=e.clientY-start[1];if(Math.abs(dx)+Math.abs(dy)>4)moved=true;state.panX=origin[0]+dx;state.panY=origin[1]+dy;can.style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.zoom})`});work.addEventListener('pointerup',()=>{down=false;can.classList.remove('dragging');if(moved)state.dragBlock=Date.now()+200});work.addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();state.zoom=Math.max(.5,Math.min(1.6,state.zoom+(e.deltaY>0?-.05:.05)));can.style.transform=`translate(${state.panX}px,${state.panY}px) scale(${state.zoom})`;$('.zoom-text').textContent=Math.round(state.zoom*100)+'%'}},{passive:false})}
function closeDrawer(){ $('#drawer-root').innerHTML='';state.selected=null; }
function showDrawer(id){if(state.dragBlock>Date.now())return;state.selected=id;const p=person(id);$$('.person-node').forEach(n=>n.classList.toggle('selected',n.dataset.id===id));const sources=data.sources.filter(s=>s.person===id);$('#drawer-root').innerHTML=`<div class="drawer-scrim" data-action="close-drawer"></div><aside class="person-drawer" role="dialog" aria-modal="true" aria-label="${esc(p.name)}人物摘要"><div class="drawer-top"><span>人物摘要 · ${pID(p)}</span>${button(icon('close'),'close-drawer','close-btn','aria-label="关闭人物摘要"')}</div><div class="drawer-person">${avatar(p,'large')}<h2>${esc(p.name)}</h2><div class="small muted">${lifespan(p)}</div><span class="tag">${esc(p.relation||'家族成员')}${!p.death?' · 受限可见':''}</span></div><div class="drawer-primary"><a class="btn btn-primary" href="#person/${id}/details">查看人物资料</a>${button(icon('star')+(data.followed.includes(id)?'已关注':'关注人物'),'follow-person','btn',`data-id="${id}"`)}</div><div class="drawer-details"><h3>人生中的重要信息</h3><div class="info-pair"><span>出生</span><strong>${esc(p.birth)}年 · ${esc(p.place||'地点待补')}</strong></div><div class="info-pair"><span>祖籍</span><strong>${esc(p.origin||'待补充')}</strong></div>${p.style?`<div class="info-pair"><span>字 / 号</span><strong>${esc(p.style)}</strong></div>`:''}<div class="info-pair"><span>关系</span><strong>${esc(p.relation||'家族成员')} · ${p.death?'历史人物':'家庭授权可见'}</strong></div></div><div class="drawer-metrics"><div><strong>${sources.length}</strong><span>条来源</span></div><div><strong>${data.memories.filter(m=>m.person===id).length}</strong><span>段记忆</span></div><div><strong>${p.father?2:0}</strong><span>位父母</span></div></div><div class="hint-card"><h4>${icon('book')} 让每条记载都有出处</h4><p style="margin:0">${sources.length?'已有来源可供查看。不同记载分别保留，重要修改需要说明理由。':'还可以为这位家人补充谱页、照片或一段讲述。'}</p><a class="btn btn-sm" href="#person/${id}/sources">查看来源与依据</a></div></aside>`;$('.person-drawer .close-btn').focus()}
function profileView(){const p=person(state.person),sources=data.sources.filter(s=>s.person===p.id),memories=data.memories.filter(m=>m.person===p.id);const tabs=[['details','资料',''],['timeline','时间线',''],['sources','来源',sources.length],['memories','记忆',memories.length],['changes','变更记录','']];let content='';
 if(state.tab==='details')content=`<section class="panel"><div class="panel-head"><h2>基本资料</h2>${button(icon('edit')+' 编辑资料','edit-person','text-link',`data-id="${p.id}"`)}</div><div class="panel-body fact-grid">${[['姓名',p.name,'原文名讳'],['性别',p.sex==='M'?'男':'女',''],['出生',p.birth+'年',p.place||'地点待补'],['逝世',p.death?p.death+'年':'在世',p.death?'年份精度：年':'仅授权家人可见'],['祖籍',p.origin||'待补充','原籍与现居地分别保存'],['字 / 号',p.style||'待补充',p.style?'来源：演示谱页':'保留原文字形']].map(([l,v,s])=>`<div class="fact"><label>${l}</label>${esc(v)}<small>${esc(s)}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>生平简述</h2><span class="tag">家庭整理</span></div><div class="panel-body" style="font-size:12px;color:#728068;line-height:2">${esc(p.bio||'这位家人的故事还在整理中。你可以补充一段讲述，并关联对应的来源。')}</div></section><section class="panel"><div class="panel-head"><h2>家庭成员</h2>${button(icon('plus')+' 补充关系','add-person','text-link')}</div><div class="panel-body">${[p.father,p.mother,p.spouse,...data.people.filter(x=>x.father===p.id||x.mother===p.id).map(x=>x.id)].filter(Boolean).map(id=>{const m=person(id);return `<div class="family-member">${avatar(m)}<span><strong>${esc(m.name)}</strong><small>${lifespan(m)} · ${id===p.father?'父亲':id===p.mother?'母亲':id===p.spouse?'配偶':'子女'}</small></span><a class="text-link" href="#person/${id}/details">资料 ${icon('chevron-right')}</a></div>`}).join('')||'<p class="small muted">还没有录入家庭关系。</p>'}</div></section>`;
 else if(state.tab==='sources')content=`<section class="panel"><div class="panel-head"><h2>来源与依据</h2>${button(icon('plus')+' 添加来源','add-source','btn btn-sm',`data-id="${p.id}"`)}</div><div class="panel-body">${sources.length?sources.map((s,i)=>`<article class="source-row"><span class="source-number">${i+1}</span><div><h4>${esc(s.title)}</h4><p>${esc(s.desc)}</p><span class="tag">${esc(s.type)}</span> <span class="small muted">关联人物基本资料</span></div>${button('查看','source','btn btn-sm',`data-id="${s.id}"`)}</article>`).join(''):'<div class="empty-state">'+icon('file')+'<p>还没有关联来源，可上传一份文稿或添加出处。</p></div>'}</div></section>`;
 else if(state.tab==='timeline')content=`<section class="panel"><div class="panel-head"><h2>人生时间线</h2><a class="text-link" href="#roots">查看迁徙线索 ${icon('pin')}</a></div><div class="panel-body"><div class="timeline">${(p.id==='p3'?[['1924','出生于福建南安','谱页记载出生年份，具体日期待补充。','s1'],['约1948','迁居线索：金门','家人口述提及，具体年份尚待文献核对。','s3'],['约1950','在台南生活','家书与口述共同提供地点线索。','s2'],['1962','寄出一封家书','保留原文与原件副本，连接两地家人记忆。','s2'],['2003','家人记载的逝世年份','由家庭成员补录，具体出处可继续补充。',null]]:[[p.birth,'出生',p.place||'地点待补',null],[p.death||'现在',p.death?'家人记载的逝世年份':'家庭故事正在继续',p.bio||'等待家人补充新的事件。',null]]).map(([y,t,d,s])=>`<article class="timeline-event"><div class="year">${esc(y)}</div><h4>${esc(t)}</h4><p>${esc(d)}</p>${s?button('查看依据','source','text-link',`data-id="${s}"`):'<span class="tag amber">待补来源</span>'}</article>`).join('')}</div></div></section>`;
 else if(state.tab==='memories')content=`<section class="panel"><div class="panel-head"><h2>与${esc(p.name)}有关的记忆</h2>${button(icon('plus')+' 添加记忆','upload-memory','btn btn-sm',`data-person="${p.id}"`)}</div><div class="panel-body"><div class="memory-grid" style="grid-template-columns:1fr 1fr">${memories.map(memoryCard).join('')}</div>${memories.length?'':'<div class="empty-state">还没有关联记忆。</div>'}</div></section>`;
 else content=`<section class="panel"><div class="panel-head"><h2>变更记录</h2><span class="small muted">修改可追溯</span></div><div class="panel-body">${[...data.activities.map(a=>[a.text,a.time]),['林知远关联了谱页和家书来源','2026年10月23日'],['林建民补充了人物生平简述','2026年10月21日'],['创建人物档案并保留原文名讳','2026年10月20日']].slice(0,8).map(([t,d])=>`<div class="change">${esc(t)}<small>${esc(d)} · 家庭编辑记录</small></div>`).join('')}</div></section>`;
 return `<div class="profile-page"><section class="profile-hero"><div class="profile-hero-inner"><div class="breadcrumb"><a href="#tree">家族树</a> / 人物资料 / ${esc(p.name)}</div><div class="profile-heading">${avatar(p,'xlarge')}<div><h1>${esc(p.name)}</h1><div class="profile-identity">${lifespan(p)} <span style="padding:0 10px">·</span>${pID(p)}</div><div class="small muted" style="margin-top:8px">${esc(p.relation||'家族成员')} ${p.style?' · '+esc(p.style):''} ${!p.death?' · 在世人物，受限可见':''}</div></div><div class="actions">${button(icon('star')+(data.followed.includes(p.id)?'已关注':'关注'),'follow-person','btn btn-sm',`data-id="${p.id}"`)}<a class="btn btn-primary btn-sm" href="#tree">${icon('tree')} 查看家族树</a></div></div><div class="profile-tabs">${tabs.map(([key,t,n])=>`<button data-action="profile-tab" data-tab="${key}" class="${state.tab===key?'active':''}">${t}${n!==''?`<span class="tab-count">${n}</span>`:''}</button>`).join('')}</div></div></section><div class="profile-body"><div class="profile-main">${content}</div><aside class="profile-aside"><section class="panel"><div class="panel-head"><h3>资料整理提示</h3>${icon('sparkles')}</div><div class="panel-body"><div class="hint-row">${icon('book')}<p>核对原文字形与年份<small>保留谱页和口述的不同记载</small></p></div><div class="hint-row">${icon('pin')}<p>补充古今地名依据<small>不以同姓、同堂号直接认定亲缘</small></p></div><a href="#studio" class="text-link" style="margin-top:15px">打开 AI 整理助手 ${icon('arrow-right')}</a></div></section><section class="panel"><div class="panel-head"><h3>我的亲属关系</h3></div><div class="panel-body"><p>林知远 → ${esc(p.relation||'家族成员')} ${esc(p.name)}</p>${button('查看关系路径','relationship','text-link',`data-id="${p.id}"`)}</div></section><section class="panel"><div class="panel-head"><h3>研究笔记</h3>${button(icon('plus'),'add-note','icon-btn',`data-id="${p.id}" aria-label="添加研究笔记"`)}</div><div class="panel-body">${data.notes.filter(n=>n.person===p.id).map(n=>`<p>${esc(n.text)}</p>`).join('')||'<p class="muted">先记下疑问，等找到资料后再确认。</p>'}</div></section></aside></div></div>`;
}
function audioArt(){return `<div class="audio-art">${Array.from({length:39},(_,i)=>`<i style="height:${16+Math.sin(i*1.4)*14+(i%7)*5}px"></i>`).join('')}<span class="big-play">${icon('play')}</span></div>`}
function memoryCard(m){return `<article class="memory-card"><div class="memory-image" data-action="memory" data-id="${m.id}" tabindex="0" role="button" aria-label="打开${esc(m.title)}">${m.image?`<img src="${m.image}" alt="${esc(m.title)}">`:m.type==='audio'?audioArt():`<div class="story-art"><span>把故事，<br>留给后来。</span><small>FAMILY STORIES</small></div>`}<span class="memory-type">${icon(m.type==='image'?'image':m.type==='audio'?'mic':m.type==='story'?'book':'file')}${{image:'图像',audio:'声音',story:'故事',document:'文稿'}[m.type]||'记忆'}</span>${button(icon('star'),'save-memory','memory-save '+(data.favorites.includes(m.id)?'saved':''),`data-id="${m.id}" aria-label="${data.favorites.includes(m.id)?'取消收藏':'收藏'}${esc(m.title)}"`)}</div><div class="memory-card-body"><h3 data-action="memory" data-id="${m.id}" role="button" tabindex="0">${esc(m.title)}</h3><p>${esc(m.desc)}</p><div class="memory-meta"><span class="memory-person">${avatar(person(m.person))}${esc(person(m.person).name)}</span><span>${esc(m.year)} · ${icon('lock')} ${esc(m.privacy||'家庭成员')}</span></div></div></article>`}
function memoriesView(){let ms=data.memories.filter(m=>(state.memoryFilter==='all'||(state.memoryFilter==='saved'?data.favorites.includes(m.id):m.type===state.memoryFilter))&&(!state.memoryQuery||(m.title+m.desc+person(m.person).name).includes(state.memoryQuery)));return `<div class="page"><div class="page-header"><div><div class="eyebrow">FAMILY MEMORIES</div><h1>家的记忆，都在这里。</h1><p>一张照片、一封家书、一段声音，连起家人的生活。</p></div>${button(icon('plus')+' 添加记忆','upload-memory','btn btn-primary')}</div><div class="toolbar"><div class="pill-tabs">${[['all','全部'],['image','图像'],['audio','声音'],['story','故事'],['document','文稿'],['saved','我的收藏']].map(([v,t])=>`<button class="${state.memoryFilter===v?'active':''}" data-action="memory-filter" data-filter="${v}">${t}</button>`).join('')}</div><div class="search-field">${icon('search')}<input id="memory-search" aria-label="搜索家庭记忆" placeholder="搜索记忆或人物" value="${esc(state.memoryQuery)}"></div></div><div id="memory-results"><div class="memory-grid">${ms.map(memoryCard).join('')}</div>${!ms.length?'<div class="empty-state">'+icon('image')+'<p>没有找到相关记忆，试试其他分类或关键词。</p></div>':''}</div>${footer()}</div>`}
function rootsView(){return `<div class="page"><section class="roots-banner"><div class="roots-banner-copy"><div class="eyebrow">ROOTS ACROSS THE STRAIT</div><h1>山海之间，<br>有家人留下的线索。</h1><p>从祖籍、家书和旧谱出发，核对台湾与闽南之间的家族联结，让每一段迁徙都有资料可循。</p>${button(icon('plus')+' 补充一条寻根线索','add-clue','btn btn-primary')}</div><div class="roots-banner-art" role="img" aria-label="山海原创示意插画"></div></section><div class="roots-grid"><section class="panel"><div class="panel-head"><h2>林文海的迁徙线索</h2><span class="tag amber">部分年份待核</span></div><div class="panel-body"><div class="migration-map"><svg viewBox="0 0 640 270" role="img" aria-label="福建南安经金门至台湾台南的迁徙示意，非导航地图"><path d="M0 0H250L275 48 250 87 281 125 237 180 261 218 232 270H0" fill="#e7eddd"/><path d="M492 15Q548 31 550 91Q551 162 494 233Q470 253 451 241Q446 223 459 183Q479 136 472 96Q468 57 492 15" fill="#e0e8d4"/><text x="78" y="45" class="map-small">福建 · 闽南</text><text x="491" y="105" class="map-small">台湾</text><text x="332" y="215" class="map-small" style="letter-spacing:5px;fill:#b2bda3">台湾海峡</text><path class="map-route" d="M194 107Q234 111 282 134T482 190"/><g class="map-point" data-action="source" data-id="s1" role="button" tabindex="0" aria-label="查看南安祖籍来源"><circle cx="194" cy="107" r="12" fill="#f9fbf3" stroke="#8ea76a"/><circle cx="194" cy="107" r="4" fill="#789653"/><text x="155" y="83" class="map-label">泉州 · 南安</text><text x="149" y="138" class="map-small">祖籍与出生地</text></g><g class="map-point" data-action="source" data-id="s3" role="button" tabindex="0" aria-label="查看金门口述线索"><circle cx="292" cy="136" r="9" fill="#f8f2e6" stroke="#b49e6f"/><circle cx="292" cy="136" r="3" fill="#b49e6f"/><text x="281" y="112" class="map-label">金门</text><text x="274" y="164" class="map-small">口述线索</text></g><g class="map-point" data-action="source" data-id="s2" role="button" tabindex="0" aria-label="查看台南家书依据"><circle cx="482" cy="190" r="12" fill="#f9fbf3" stroke="#8ea76a"/><circle cx="482" cy="190" r="4" fill="#789653"/><text x="505" y="194" class="map-label">台南</text><text x="475" y="224" class="map-small">家书寄出地</text></g></svg></div><div class="route-steps"><div class="route-step"><small>1924年</small><strong>福建南安</strong><br>谱页记录出生地</div><div class="route-step"><small>约1948年 · 待核</small><strong>金门</strong><br>家人口述迁居线索</div><div class="route-step"><small>1962年</small><strong>台湾台南</strong><br>家书记载通信地点</div></div><div class="roots-note">示意路线不代表精确行程。地点与年份按不同来源分别保存，点击地点查看依据。</div></div></section><section class="panel"><div class="panel-head"><h2>待核对的资料</h2><span class="tag">${data.linked?'已建立1条关联':'1 条候选关联'}</span></div><div class="panel-body"><article class="clue"><h4>两地谱本中的“林文海”</h4><p>名讳、字“承远”与出生年份相近。需要继续比较父母、房支及原始记载。</p><span class="tag ${data.linked?'green':'amber'}">${data.linked?'已确认关联 · 可追溯':'待人工核对 · 不自动合并'}</span><div style="margin-top:15px">${button('并排核对谱本 '+icon('arrow-right'),'compare','text-link')}</div></article><article class="clue"><h4>旧地名“泉州南安”</h4><p>保存原文地名，现代对应暂定福建泉州南安，村里层级仍需补充文献。</p>${button('查看地名说明','place-info','text-link')}</article><a href="#person/p3/sources" class="text-link" style="margin-top:18px">浏览人物全部来源 ${icon('arrow-right')}</a></div></section></div><div class="section-heading"><h2>让线索和证据放在一起</h2><a class="text-link" href="#person/p3/details">查看林文海资料 ${icon('arrow-right')}</a></div><section class="panel" style="overflow:auto"><table class="evidence-table"><thead><tr><th>来源资料</th><th>提供的线索</th><th>状态</th><th></th></tr></thead><tbody>${data.sources.filter(s=>s.person==='p3').map((s,i)=>`<tr><td>${esc(s.title)}<small>${esc(s.year)} · ${esc(s.type)}</small></td><td>${i===0?'名讳、字辈与祖籍':i===1?'台南通信地点与家人往来':'迁居经历及待核年份'}</td><td><span class="tag ${i===2?'amber':'green'}">${i===2?'口述待核':'已关联出处'}</span></td><td>${button('查看','source','text-link',`data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table></section>${footer()}</div>`}
function studioView(){let content;const mode=state.studioMode;if(mode==='ocr')content=ocrContent();else if(mode==='interview')content=interviewContent();else content=chatContent();return `<div class="page"><div class="page-header"><div><div class="eyebrow">ASSISTED BY AI · CONFIRMED BY FAMILY</div><h1>让整理轻一点，让记忆多一点。</h1><p>AI 帮助提取线索，家人确认事实。每一步都保留原始资料。</p></div><span class="tag">预置样本演示</span></div><div class="studio-layout"><aside class="panel studio-sidebar">${[['ocr','book','老谱识别与校勘','原图与文字并排核对'],['interview','mic','口述史与家庭访谈','从一个故事继续追问'],['chat','sparkles','有来源的家族问答','回答关联到具体资料']].map(([v,ic,t,s])=>`<button data-action="studio-mode" data-mode="${v}" class="${mode===v?'active':''}">${icon(ic)}<span>${t}<small>${s}</small></span></button>`).join('')}</aside><section class="panel studio-main">${content}</section></div>${footer()}</div>`}
function ocrContent(){return `<div class="studio-intro"><h2>把一页老谱，接回家族故事。</h2><p>识别、对照、确认；原始谱页与编辑结果分别保存。</p></div><div class="studio-content"><div class="stepper"><span class="${state.ocrStage===1?'active':''}"><i>1</i>选择谱页</span><b></b><span class="${state.ocrStage===2?'active':''}"><i>2</i>人工核对</span><b></b><span class="${state.ocrStage===3?'active':''}"><i>3</i>确认关联</span></div>${state.ocrStage===1?`<div class="upload-zone">${icon('upload')}<h3>选择家里保存的谱页</h3><p>可上传图片预览，或直接使用本次体验的演示谱页。</p>${button('选择图片','ocr-file','btn btn-sm')}<input type="file" accept="image/*" id="ocr-file" class="hidden"></div><div class="sample-file"><img src="${state.ocrPreview||'assets/genealogy.svg'}" alt="所选谱页预览"><div><strong>${state.ocrPreview?'本地图片预览':'演示谱页 · 林氏家谱 卷二'}</strong><small>${state.ocrPreview?'仅在当前浏览器预览，不上传服务器':'虚构样本 · 包含人物名讳、字与籍贯'}</small></div><span class="tag">${state.ocrPreview?'本地预览':'可直接体验'}</span></div>${button('体验样例识别与核对 '+icon('arrow-right'),'ocr-run','btn btn-primary')}<p class="studio-note">原型不调用真实识别服务。下一步展示预置谱页结果；上传其他图片仅预览，不会生成对应识别结果。</p>`:state.ocrStage===2?`<div class="ocr-review"><img src="assets/genealogy.svg" alt="预置演示谱页原文"><div class="review-fields"><div class="field"><label>名讳 <span class="tag green">原文保留</span></label><input id="ocr-name" value="林文海" aria-label="核对名讳"></div><div class="field"><label>字 / 号</label><input id="ocr-style" value="字承远" aria-label="核对字或号"></div><div class="field"><label>出生年份 <span class="tag amber">请核对</span></label><input id="ocr-birth" value="1924" aria-label="核对出生年份"><div class="review-warning">年份来自样例资料，确认前请对照原文。</div></div><div class="field"><label>原籍</label><input id="ocr-place" value="福建 泉州 南安" aria-label="核对原籍"></div><p class="studio-note">关联至已有档案：林文海 JX-0003。只补充选定字段和来源，不自动新增或合并人物。</p></div></div><label class="check-row"><input type="checkbox" id="ocr-confirm">我已核对示例字段，同意将结果与谱页来源关联到人物档案。</label><div class="actions">${button('返回选择','ocr-back','btn')}${button('确认并关联人物 '+icon('check'),'ocr-confirm','btn btn-primary')}</div>`:`<div class="success-state"><span class="success-icon">${icon('check')}</span><h2>这页记载，已接回人物档案。</h2><p>已保留演示原图、确认字段与编辑记录。<br>资料仍可继续核对与修订。</p><div class="actions" style="justify-content:center;margin-top:23px"><a class="btn btn-primary" href="#person/p3/sources">查看林文海的来源 ${icon('arrow-right')}</a>${button('再体验一次','ocr-back','btn')}</div></div>`}</div>`}
function interviewContent(){return `<div class="studio-intro"><h2>先听家人讲，再慢慢整理。</h2><p>录音、转写与故事分开保留；生成的内容由家人确认。</p></div><div class="studio-content"><div class="recording-panel"><span class="tag">本次访谈：祖母的年节记忆 · 虚构样例</span><button class="record-button ${state.interviewStep===1?'recording':''}" data-action="interview-toggle" aria-label="${state.interviewStep===1?'结束演示访谈':'开始演示访谈'}">${icon(state.interviewStep===1?'pause':'mic')}</button><h3>${state.interviewStep===0?'从一个熟悉的问题开始':state.interviewStep===1?'正在体验访谈流程':'讲述已整理为样例转写'}</h3><p class="small muted" style="font-size:11px;margin:0">${state.interviewStep===1?'点击结束，查看预置转写与追问。未启用麦克风。':'“小时候，家里过年最让你难忘的是什么？”'}</p></div>${state.interviewStep>=2?`<div class="interview-transcript"><h4>样例转写 ${button(icon('volume')+' 朗读文字','speak','text-link',`data-id="m3"`)}</h4><p style="margin-bottom:10px">${esc(data.memories.find(m=>m.id==='m3').body)}</p><span class="tag">转写样例 · 尚未保存为新故事</span></div><div class="interview-transcript" style="background:#f9faf6"><h4>可以继续问</h4><p>那时候，家里通常是谁负责写春联？<br>有没有一道年菜，是每年一定会做的？</p><div class="actions">${button('保存为家庭故事','save-interview','btn btn-primary btn-sm')}${button('重新体验','interview-reset','btn btn-sm')}</div></div>`:''}<p class="studio-note">本次演示使用预置转写，不采集麦克风。正式产品将支持经同意录音、对应音频片段和人工修订。</p></div>`}
function chatContent(){return `<div class="studio-intro"><h2>问问家里的资料。</h2><p>只基于授权资料回答，给出出处；没有依据时保留疑问。</p></div><div class="studio-content"><div class="chat-list" id="chat-list">${state.chat.length?state.chat.map(m=>m.role==='user'?`<div class="chat-question">${esc(m.text)}</div>`:`<div class="chat-answer"><h4>${icon('sparkles')} 基于已关联的家庭资料</h4><p>${esc(m.text)}</p>${m.sources.length?`<div class="chat-citations">${m.sources.map(id=>button(icon('file')+' '+esc(data.sources.find(s=>s.id===id)?.title||'资料来源'),'source','',`data-id="${id}"`)).join('')}</div>`:'<span class="tag amber">资料不足，不能推定</span>'}<div class="tiny muted" style="margin-top:9px">预置问答逻辑演示，非实时模型回答。</div></div>`).join(''):`<div class="empty-state" style="padding:34px 10px">${icon('sparkles')}<h3 style="font-size:16px;color:#647d4b">让零散的记载，回答具体的问题。</h3><p class="small">试着了解祖父的来处，或看看一封家书留下了什么。</p></div>`}</div><form id="chat-form" class="chat-input"><input id="chat-question" placeholder="例如：祖父林文海从哪里迁到台南？" aria-label="向家庭资料提问" required maxlength="300"><button class="btn btn-primary" type="submit" aria-label="发送问题">${icon('arrow-right')}</button></form><div class="suggested-questions">${['林文海从哪里迁到台南？','这封家书记载了什么？','我们和另一本林氏家谱能确认亲缘吗？'].map(q=>button(esc(q),'suggest-question','',`data-question="${esc(q)}"`)).join('')}</div><p class="studio-note">本次演示仅提供有限样例回答。正式问答需接入模型、权限检索、来源定位和质量评估。</p></div>`}
let lastFocus=null;
function modal(title,content,foot='',wide=false){closeDrawer();lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay" data-action="overlay-close"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2>${button(icon('close'),'close-modal','close-btn','aria-label="关闭对话框"')}</header><div class="modal-content">${content}</div>${foot?`<footer class="modal-footer">${foot}</footer>`:''}</section></div>`;const f=$('.modal input:not([type=file]),.modal textarea,.modal .close-btn');f?.focus()}
function closeModal(){const was=$('#modal-root').innerHTML;$('#modal-root').innerHTML='';if(was&&lastFocus?.isConnected)lastFocus.focus()}
function searchDialog(){modal('在家族里找一找',`<div class="search-field" style="max-width:none">${icon('search')}<input id="global-search" placeholder="搜索姓名、字、地点或记忆标题" aria-label="搜索姓名或记忆"></div><div class="search-results" id="global-search-results">${searchResults('')}</div>`);$('#global-search').focus()}
function searchResults(q){const ps=data.people.filter(p=>(p.name+(p.style||'')+(p.place||'')).includes(q)).slice(0,8),ms=q?data.memories.filter(m=>(m.title+m.desc).includes(q)).slice(0,4):[];return ps.map(p=>`<a class="search-result" href="#person/${p.id}/details">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${lifespan(p)} · ${esc(p.relation||'家人')} · ${pID(p)}</small></span>${icon('arrow-right')}</a>`).join('')+ms.map(m=>`<button class="search-result" data-action="memory" data-id="${m.id}">${icon('image')}<span><strong>${esc(m.title)}</strong><small>家庭记忆 · ${esc(m.year)}</small></span>${icon('arrow-right')}</button>`).join('')||'<div class="empty-state" style="padding:25px">没有找到相关人物或记忆。</div>'}
function showMemory(id){const m=data.memories.find(m=>m.id===id);if(!m)return;modal(esc(m.title),`<div class="memory-viewer">${m.image?`<img src="${m.image}" alt="${esc(m.title)}">`:`<div style="height:265px;border-radius:8px;overflow:hidden">${m.type==='audio'?audioArt():`<div class="story-art"><span>家的故事，<br>慢慢讲。</span></div>`}</div>`}<div><div class="actions" style="margin-bottom:16px"><span class="tag">${esc(m.year)}</span><span class="tag">${icon('lock')} ${esc(m.privacy)}</span></div><p class="story-text">${esc(m.body||m.desc)}</p><div class="family-member">${avatar(person(m.person))}<span><strong>${esc(person(m.person).name)}</strong><small>已关联人物</small></span><a class="text-link" href="#person/${m.person}/memories">人物记忆 ${icon('arrow-right')}</a></div>${m.type==='audio'?`<div class="audio-player">${button(icon('volume')+' 朗读样例转写','speak','btn btn-sm',`data-id="${m.id}"`)}<p>演示未附原始录音；此按钮使用设备文字朗读。</p></div>`:''}<div class="actions" style="margin-top:18px">${button(icon('star')+(data.favorites.includes(id)?'已收藏':'收藏记忆'),'save-memory','btn btn-sm',`data-id="${id}"`)}${button(icon('share')+' 分享设置','share-memory','btn btn-sm',`data-id="${id}"`)}</div></div></div>`,'',true)}
function sourceDialog(id){const s=data.sources.find(s=>s.id===id);if(!s)return;modal('来源资料',`<div class="source-document"><img src="${s.image||'assets/genealogy.svg'}" alt="${esc(s.title)}原始示意资料"><div><span class="tag">虚构演示资料</span><h3 style="margin-top:17px">${esc(s.title)}</h3><p class="muted">${esc(s.desc)}</p><label>原文摘录</label><p class="serif" style="font-size:17px">${esc(s.quote)}</p><label>关联人物</label><p><a href="#person/${s.person}/sources" class="text-link">${esc(person(s.person).name)} · 查看人物来源 ${icon('arrow-right')}</a></p><label>资料处理</label><p>原文、图像与整理结果分别保存。重要事实需要人工核对；同名或同堂号不直接认定亲缘。</p></div></div>`,'',true)}
function personForm(id){const p=id?person(id):null;modal(p?'编辑人物资料':'添加一位家人',`<p class="modal-description">从已知的名字开始。日期和地点可以以后补充，在世人物默认仅授权家人可见。</p><form id="person-form" data-id="${id||''}"><div class="form-grid"><div class="field"><label for="person-name">姓名 *</label><input id="person-name" name="name" value="${esc(p?.name||'')}" required maxlength="30" placeholder="请输入姓名"></div><div class="field"><label for="person-sex">性别</label><select id="person-sex" name="sex"><option value="M">男</option><option value="F" ${p?.sex==='F'?'selected':''}>女</option></select></div><div class="field"><label for="person-birth">出生年份</label><input id="person-birth" name="birth" inputmode="numeric" pattern="[0-9]{0,4}" value="${esc(p?.birth||'')}" maxlength="4" placeholder="例如 1960"></div><div class="field"><label for="person-death">逝世年份，留空表示在世</label><input id="person-death" name="death" inputmode="numeric" pattern="[0-9]{0,4}" value="${esc(p?.death||'')}" maxlength="4" placeholder="在世请留空"></div><div class="field full"><label for="person-place">出生地</label><input id="person-place" name="place" value="${esc(p?.place||'')}" placeholder="按原始记载填写，可暂不填写"></div>${!p?`<div class="field"><label for="person-relative">关联到家人</label><select id="person-relative" name="relative">${data.people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="person-relationship">关系</label><select id="person-relationship" name="relationship"><option value="child">子女</option><option value="father">父亲</option><option value="mother">母亲</option><option value="spouse">配偶</option></select></div>`:`<div class="field full"><label for="person-reason">修改说明 *</label><input id="person-reason" name="reason" required placeholder="说明修改依据，保留编辑记录"></div>`}<div class="field full"><label for="person-bio">生平简述</label><textarea id="person-bio" name="bio" rows="3" maxlength="1500">${esc(p?.bio||'')}</textarea></div></div><div class="modal-footer" style="padding:16px 0 0;margin-top:8px;background:none">${button('取消','close-modal','btn')}<button class="btn btn-primary" type="submit">${p?'保存修改':'保存人物'}</button></div></form>`)}
function uploadMemory(personId){modal('保存一段家庭记忆',`<p class="modal-description">文件仅保存在当前浏览器，不会上传。建议演示图片小于2MB；请勿上传真实敏感家庭资料。</p><form id="memory-form"><div class="form-grid"><div class="field full"><label for="memory-title">记忆标题 *</label><input id="memory-title" name="title" required maxlength="60" placeholder="例如：院子里的团圆饭"></div><div class="field"><label for="memory-type">记忆类型</label><select id="memory-type" name="type"><option value="image">图像</option><option value="story">文字故事</option><option value="document">文稿图像</option></select></div><div class="field"><label for="memory-year">记忆年份</label><input id="memory-year" name="year" maxlength="10" placeholder="例如 1986"></div><div class="field full"><label for="memory-file">选择图片，可留空</label><input type="file" id="memory-file" accept="image/*"><div class="tiny muted" style="margin-top:7px">JPG / PNG / WebP，2MB以内；图像记忆需要选择文件。</div></div><div class="field"><label for="memory-person">关联家人</label><select id="memory-person" name="person">${data.people.map(p=>`<option value="${p.id}" ${p.id===(personId||'p0')?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label for="memory-privacy">可见范围</label><select id="memory-privacy" name="privacy"><option>家庭成员</option><option>仅自己</option></select></div><div class="field full"><label for="memory-body">这段记忆的故事 *</label><textarea id="memory-body" name="body" required maxlength="4000" placeholder="是谁，在什么地方，发生了什么……"></textarea></div></div><div class="modal-footer" style="padding:16px 0 0;background:none">${button('取消','close-modal','btn')}<button type="submit" class="btn btn-primary">保存记忆</button></div></form>`)}
function invitation(){modal('邀请家人，一起续写',`<p class="modal-description">演示家庭邀请的角色与隐私设置。本次体验不发送消息，也不创建真实成员权限。</p><div class="field"><label for="invite-role">邀请加入的角色</label><select id="invite-role"><option>普通成员，可补充记忆</option><option>编辑成员，可提交资料修改</option><option>只读成员，仅查看授权资料</option></select></div><label class="check-row"><input type="checkbox" checked disabled>新成员仅能访问家庭授权范围内的资料。</label><div class="share-box" id="invite-link">家续演示邀请码：JX-LIN-2026<br><span class="tiny muted">仅用于界面评审，不具有真实邀请效力</span></div>`,button('取消','close-modal','btn')+button(icon('copy')+' 复制演示邀请码','copy-invite','btn btn-primary'))}
function compareDialog(){modal('两地谱本 · 人物线索核对',`<p class="modal-description">各谱保留独立资料与版本。核对的是候选关联，确认后也不合并原始谱本。</p><div class="comparison-grid"><div class="comparison-column"><span class="tag">闽南谱本</span><h3 style="margin-top:12px">南安林氏家谱 · 卷二</h3><img src="assets/genealogy.svg" alt="虚构闽南谱本"><dl><dt>名讳 / 字</dt><dd>林文海 / 承远</dd><dt>出生年</dt><dd>1924年</dd><dt>父母</dt><dd>林宗源 / 黄秀英</dd><dt>原籍</dt><dd>泉州南安，村里层级待核</dd></dl></div><div class="comparison-column"><span class="tag">台湾家藏记载</span><h3 style="margin-top:12px">台南家庭补记</h3><img src="assets/letter.svg" alt="虚构台南家藏记载"><dl><dt>名讳 / 字</dt><dd>林文海 / 承遠</dd><dt>出生年</dt><dd>1924年</dd><dt>父母</dt><dd>林宗源 / 黃秀英</dd><dt>原籍</dt><dd>南安，依据家人口述</dd></dl></div></div><div class="comparison-decision"><span class="tag amber">同姓、同堂号及繁简字形只能作为检索线索</span><label><input type="checkbox" id="compare-confirm" ${data.linked?'checked':''}>我已对照示例父母、年代与原文来源，理解保留两谱独立记录。</label><div class="field"><label for="compare-reason">关联说明 *</label><textarea id="compare-reason" placeholder="说明核对依据，保留给后续审核人" rows="2">${data.linked?'已核对样例父母姓名、年代与字辈，建立演示关联。':''}</textarea></div></div>`,button('暂不关联','close-modal','btn')+button(data.linked?'解除演示关联':'确认建立关联','confirm-link','btn btn-primary'),true)}
function guide(){modal('从一个名字，体验一段家族故事',`<p class="modal-description">建议按以下路径体验。所有示例内容均为虚构，本次原型用于评审页面与交互。</p><div class="guide-list">${[['01','浏览家族树','切换横向树、扇形图和后代图，点击人物展开摘要。','tree'],['02','走进人物资料','查看林文海的家庭关系、时间线、来源与记忆。','person/p3/details'],['03','整理一页老谱','体验样例识别、人工校勘与确认关联。','studio'],['04','核对闽台线索','比较两地谱本并保留独立来源。','roots'],['05','保存一段记忆','浏览图像、家书与声音，也可以添加本地演示资料。','memories']].map(([n,t,d,url])=>`<a class="guide-item" href="#${url}"><span class="step-num">${n}</span><div><h3>${t}</h3><p>${d}</p></div>${icon('arrow-right')}</a>`).join('')}</div>`)}
function answerQuestion(q){if(!q.trim())return;data;const keyword=q.trim();state.chat.push({role:'user',text:keyword});let text,sources;if(/迁|哪里|祖籍|台南|来处/.test(keyword)){text='在演示资料中，林文海的原籍记为福建泉州南安。家人口述提及金门，1962年家书显示台南通信地点。可以把它们保存为待核迁徙线索，但现有资料还不足以确认每一段行程和精确年份。';sources=['s1','s2','s3']}else if(/家书|记载|信/.test(keyword)){text='样例家书表达了对家人平安与故乡生活的牵挂，可为台南通信地点和家庭往来提供线索。它没有完整记载迁徙路线，因此不能仅据这封信确定祖籍村落或迁居时间。';sources=['s2']}else if(/亲缘|另一本|同姓|谱/.test(keyword)){text='现有样例不能单凭同姓、同堂号或“承远／承遠”的字形确认亲缘。需要对照父母、配偶、前后世代、年代和原始来源，经授权核对后才能保存候选关联。建议进入闽台寻根的两谱对照流程。';sources=['s1','s3']}else{text='目前这组家庭样例没有足够资料回答这个问题。可以先补充谱页、家书或经家人确认的口述记录，再核对相关事实。';sources=[]}state.chat.push({role:'assistant',text,sources});render();$('#chat-question')?.focus()}
function download(name,text,mime='application/json'){const blob=new Blob([text],{type:mime});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportDialog(){modal('导出家族资料',`<p class="modal-description">导出当前浏览器中的演示资料。正式平台将按授权检查导出范围，并记录导出日志。</p><div class="field"><label for="export-format">导出格式</label><select id="export-format"><option value="json">JSON 完整演示备份，含人物、记忆与来源</option><option value="gedcom">GEDCOM 5.5.1，基础人物及家庭关系</option></select></div><p class="small muted">GEDCOM 导出不包含中文扩展字段、媒体文件与审核记录。完整演示数据可选择 JSON。</p>`,button('取消','close-modal','btn')+button(icon('download')+' 下载文件','download-export','btn btn-primary'))}
function buildGedcom(){let lines=['0 HEAD','1 SOUR JIAXU-DEMO','1 GEDC','2 VERS 5.5.1','2 FORM LINEAGE-LINKED','1 CHAR UTF-8'];const families=new Map();data.people.forEach(p=>{if(p.father||p.mother){const key=(p.father||'')+'|'+(p.mother||'');if(!families.has(key))families.set(key,{id:'F'+(families.size+1),father:p.father,mother:p.mother,children:[]});families.get(key).children.push(p.id)}});data.people.forEach(p=>{lines.push(`0 @${p.id}@ INDI`,`1 NAME ${p.name}`,`1 SEX ${p.sex}`);if(p.birth||p.place)lines.push('1 BIRT');if(p.birth)lines.push(`2 DATE ${p.birth}`);if(p.place)lines.push(`2 PLAC ${p.place}`);if(p.death)lines.push('1 DEAT',`2 DATE ${p.death}`);for(const f of families.values()){if(f.children.includes(p.id))lines.push(`1 FAMC @${f.id}@`);if(f.father===p.id||f.mother===p.id)lines.push(`1 FAMS @${f.id}@`)}});for(const f of families.values()){lines.push(`0 @${f.id}@ FAM`);if(f.father)lines.push(`1 HUSB @${f.father}@`);if(f.mother)lines.push(`1 WIFE @${f.mother}@`);f.children.forEach(id=>lines.push(`1 CHIL @${id}@`))}lines.push('0 TRLR');return lines.join('\r\n')}
function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
document.addEventListener('click',async e=>{
 if(e.target.closest('a.skip-link')){e.preventDefault();$('#main').focus();return}
 const link=e.target.closest('a[href^="#"]');if(link&&link.getAttribute('href')!=='#')closeModal();
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='overlay-close'){if(e.target!==el)return;closeModal();return}if(el.tagName==='A'&&el.getAttribute('href')==='#')e.preventDefault();
 if(a==='search')searchDialog();else if(a==='guide')guide();else if(a==='close-modal')closeModal();else if(a==='close-drawer')closeDrawer();else if(a==='person-drawer')showDrawer(id);else if(a==='profile-tab')go(`person/${state.person}/${el.dataset.tab}`);
 else if(a==='tree-view'){state.treeView=el.dataset.view;closeDrawer();render()}else if(a==='tree-reset'){state.panX=0;state.panY=0;state.zoom=1;closeDrawer();render()}else if(a==='zoom-in'||a==='zoom-out'){state.zoom=Math.max(.5,Math.min(1.6,state.zoom+(a==='zoom-in'?.1:-.1)));render()}else if(a==='toggle-desc'){state.descExpanded=!state.descExpanded;render()}
 else if(a==='add-person')personForm();else if(a==='edit-person')personForm(id);else if(a==='upload-memory')uploadMemory(el.dataset.person);else if(a==='invite')invitation();else if(a==='copy-invite'){try{await navigator.clipboard.writeText('家续演示邀请码：JX-LIN-2026；角色：'+$('#invite-role').value);toast('演示邀请码已复制，不具有真实邀请效力')}catch{toast('无法自动复制，请选中并复制 JX-LIN-2026')}}
 else if(a==='members'){modal('一起整理的家人',`<p class="modal-description">演示家庭空间 · 4位协作成员</p>${[['林知远','家庭管理员'],['林建民','编辑成员'],['陈淑华','普通成员'],['沈晓雨','普通成员']].map(([n,r])=>`<div class="family-member"><span class="mini-avatar">${n[0]}</span><span><strong>${n}</strong><small>${r}</small></span><span class="tag" style="margin-left:auto">已加入</span></div>`).join('')}`,button('邀请更多家人','invite','btn btn-primary'))}
 else if(a==='notifications'){modal('家庭动态',`<div class="guide-list">${[...data.activities,{text:'林建民补充了一封演示家书',time:'昨天 16:30'},{text:'陈淑华保存了一段年节回忆',time:'10月21日'}].slice(0,7).map(x=>`<div class="guide-item">${icon('clock')}<div><h3>${esc(x.text)}</h3><p>${esc(x.time)}</p></div></div>`).join('')}</div>`)}
 else if(a==='account'){modal('林知远的家庭空间',`<div class="family-member">${avatar(person('p0'))}<div><strong>林知远 · 演示账号</strong><small>林氏家庭空间管理员</small></div></div><div class="divider"></div><p class="small muted">演示数据保存在当前浏览器。可导出备份，也可清空本次体验并恢复初始样例。</p><div class="actions">${button(icon('download')+' 导出资料','export','btn')}${button('恢复初始演示','reset-dialog','btn')}</div>`)}
 else if(a==='reset-dialog'){modal('恢复初始演示',`<p class="modal-description">将移除本原型在当前浏览器保存的人物修改、上传记忆、收藏和核对结果，恢复虚构样例。此操作不影响其他网站。</p>`,button('取消','close-modal','btn')+button('确认恢复初始演示','reset-demo','btn btn-primary'))}
 else if(a==='reset-demo'){data={people:structuredClone(peopleSeed),memories:structuredClone(memorySeed),sources:structuredClone(sourceSeed),favorites:[],followed:[],activities:[],notes:[],ocrDone:false,linked:false};save();state.ocrStage=1;state.chat=[];state.interviewStep=0;closeModal();go('home');toast('已恢复初始演示样例')}
 else if(a==='memory')showMemory(id);else if(a==='source')sourceDialog(id);else if(a==='save-memory'){e.stopPropagation();const i=data.favorites.indexOf(id);if(i>=0)data.favorites.splice(i,1);else data.favorites.push(id);save();const wasModal=!!$('.memory-viewer');render();if(wasModal)showMemory(id);toast(i>=0?'已取消收藏':'已收藏这段记忆')}
 else if(a==='memory-filter'){state.memoryFilter=el.dataset.filter;render()}else if(a==='follow-person'){const i=data.followed.indexOf(id);if(i>=0)data.followed.splice(i,1);else data.followed.push(id);save();if($('.person-drawer'))showDrawer(id);else render();toast(i>=0?'已取消关注':'已关注这位家人')}
 else if(a==='share-memory'){const m=data.memories.find(m=>m.id===id);modal('记忆分享设置',`<p class="modal-description">${esc(m.title)}</p><div class="field"><label for="share-privacy">可见范围</label><select id="share-privacy"><option ${m.privacy==='家庭成员'?'selected':''}>家庭成员</option><option ${m.privacy==='仅自己'?'selected':''}>仅自己</option></select></div><p class="small muted">仅演示本地可见范围设置，不会创建公开分享链接。</p>`,button('保存设置','save-privacy','btn btn-primary',`data-id="${id}"`))}
 else if(a==='save-privacy'){data.memories.find(m=>m.id===id).privacy=$('#share-privacy').value;save();closeModal();render();toast('已保存这段记忆的演示可见范围')}
 else if(a==='speak'){const m=data.memories.find(m=>m.id===id);if(!('speechSynthesis'in window)){toast('当前浏览器不支持文字朗读，请阅读转写内容');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(m.body);utterance.lang='zh-CN';utterance.rate=.85;utterance.onerror=()=>toast('设备没有可用的中文朗读声音，请阅读转写内容');speechSynthesis.speak(utterance);toast('正在使用设备朗读样例文字')}
 else if(a==='ocr-route'){state.studioMode='ocr';go('studio')}else if(a==='interview-route'){state.studioMode='interview';go('studio')}else if(a==='studio-mode'){state.studioMode=el.dataset.mode;render()}else if(a==='ocr-file')$('#ocr-file').click();else if(a==='ocr-run'){state.ocrStage=2;render()}else if(a==='ocr-back'){state.ocrStage=1;render()}
 else if(a==='ocr-confirm'){if(!$('#ocr-confirm').checked){toast('请先确认已核对演示原文与字段');return}const name=$('#ocr-name').value.trim(),birth=$('#ocr-birth').value.trim();if(!name||!/^\d{1,4}$/.test(birth)){toast('请填写姓名与有效出生年份');return}const p=person('p3');p.name=name;p.birth=birth;p.style=$('#ocr-style').value.trim();p.place=$('#ocr-place').value.trim();if(!data.sources.some(s=>s.id==='s4'))data.sources.push({id:'s4',title:'谱页校勘确认记录',desc:'演示识别字段经人工核对后关联，保留原文与修改记录',image:'assets/genealogy.svg',year:'2026',quote:'已核对名讳、字与原籍，出生年份仍可继续补充佐证。',type:'校勘',person:'p3'});data.ocrDone=true;logActivity('林知远完成了谱页样例核对并关联人物来源');state.ocrStage=3;render();toast('样例字段和来源已保存到人物档案')}
 else if(a==='interview-toggle'){state.interviewStep=state.interviewStep===1?2:1;render()}else if(a==='interview-reset'){state.interviewStep=0;render()}else if(a==='save-interview'){if(data.memories.some(m=>m.id==='interview-story')){toast('这段样例故事已保存，可在家庭记忆中查看');return}data.memories.unshift({id:'interview-story',title:'祖母口述 · 过年的第一笼年糕',type:'story',year:'2026',person:'p4',body:data.memories.find(m=>m.id==='m3').body,desc:'根据样例转写整理，待家人继续确认。',privacy:'家庭成员'});logActivity('保存了一段经确认的演示口述故事');toast('已保存到家庭记忆');go('memories')}
 else if(a==='suggest-question')answerQuestion(el.dataset.question);else if(a==='compare')compareDialog();else if(a==='confirm-link'){if(data.linked){data.linked=false;logActivity('解除了两谱演示关联，原谱记录分别保留');closeModal();render();toast('已解除演示关联，原始资料未合并');return}if(!$('#compare-confirm').checked||!$('#compare-reason').value.trim()){toast('请核对确认项，并填写关联依据');return}data.linked=true;data.linkReason=$('#compare-reason').value.trim();logActivity('建立了两地谱本的演示人物关联');closeModal();render();toast('已保存演示关联与核对理由，两谱仍独立保留')}
 else if(a==='add-clue'){modal('补充一条寻根线索',`<form id="clue-form"><div class="field"><label for="clue-title">线索标题 *</label><input id="clue-title" required maxlength="60" placeholder="例如：家书中的旧村名"></div><div class="field"><label for="clue-text">原始记载与出处 *</label><textarea id="clue-text" required maxlength="1500" placeholder="写下家人原话或文献名称、卷页，保留不确定之处"></textarea></div><p class="tiny muted">本次演示保存为林文海的研究笔记，待补充原件和审核。</p><button type="submit" class="btn btn-primary">保存线索</button></form>`)}
 else if(a==='place-info'){modal('保留原文地名，再核对现代位置',`<div class="info-pair"><span>原文</span><strong>泉州南安</strong></div><div class="info-pair"><span>候选</span><strong>福建省泉州市南安市</strong></div><div class="info-pair"><span>状态</span><strong>县级对应待文献核对，村里未确认</strong></div><p class="small muted">古今地名、行政归属和具体村落按时段记录。当前为演示说明，不构成具体祖籍判定。</p>`,button('查看谱页出处','source','btn btn-primary','data-id="s1"'))}
 else if(a==='relationship'){const p=person(id);modal('我的亲属关系',`<p class="modal-description">以当前已录入关系为依据，保留父母双方家族。</p><div class="share-box">林知远 ${icon('arrow-right')} ${p.id==='p3'?'父亲 林建民 '+icon('arrow-right'):''} ${esc(p.relation||'家族成员')} ${esc(p.name)}</div><p class="tiny muted" style="margin-top:17px">演示采用已记录的亲属标签；正式产品将按完整关系数据计算路径，并标明亲生、收养及过继等关系。</p>`)}
 else if(a==='add-note'){modal('添加研究笔记',`<form id="note-form" data-id="${id}"><div class="field"><label for="note-text">记录一个疑问或补充说明</label><textarea id="note-text" required maxlength="2000" placeholder="例如：需要向家人确认具体的迁居年份"></textarea></div><button type="submit" class="btn btn-primary">保存笔记</button></form>`)}
 else if(a==='add-source'){modal('添加资料来源',`<form id="source-form" data-id="${id}"><div class="field"><label for="source-title">来源名称及卷页 *</label><input id="source-title" required maxlength="120" placeholder="例如：家藏谱本 卷三 第12页"></div><div class="field"><label for="source-quote">原文或资料说明 *</label><textarea id="source-quote" required maxlength="2000" placeholder="保留原始记载，并说明资料来自何处"></textarea></div><p class="tiny muted">本次保存演示来源条目；正式产品需保存授权范围与原件附件。</p><button type="submit" class="btn btn-primary">保存并关联</button></form>`)}
 else if(a==='export')exportDialog();else if(a==='download-export'){const format=$('#export-format').value;if(format==='json')download('家续演示资料备份.json',JSON.stringify({...data,exportedAt:new Date().toISOString(),demo:true},null,2));else download('家续基础人物与家庭关系.ged',buildGedcom(),'text/plain;charset=utf-8');toast('已生成当前演示资料文件');closeModal()}
 else if(a==='about'){modal('关于家续体验原型',`<p class="modal-description">本原型用于数字族谱与家庭记忆平台的页面和交互评审。家续为暂定演示名称，全部人物、文字、谱页和插画均为虚构样例。</p><p class="small muted">家族树视图、人物分区与来源浏览参考 FamilySearch 的交互机制。家续与 FamilySearch 无隶属关系，不使用其标识，也未接入其账号、史料库或 API。</p><p class="small muted">可实际体验本地搜索、编辑、上传、收藏、导出及关联状态。AI识别、访谈和问答为预置流程演示，不连接真实模型、录音、地图或消息服务。</p><a class="text-link" href="https://www.familysearch.org/en/help/helpcenter/article/what-are-the-different-pedigree-views-in-family-tree" target="_blank" rel="noopener">FamilySearch 官方树视图说明 ${icon('external')}</a>`)}
});
document.addEventListener('submit',async e=>{const f=e.target;if(!['person-form','memory-form','note-form','source-form','chat-form','clue-form'].includes(f.id))return;e.preventDefault();
 if(f.id==='chat-form'){answerQuestion($('#chat-question').value);return}
 if(f.id==='person-form'){const v=Object.fromEntries(new FormData(f)),birth=v.birth?.trim(),death=v.death?.trim();if(birth&&death&&Number(death)<Number(birth)){toast('逝世年份不能早于出生年份');return}if(f.dataset.id){const p=person(f.dataset.id);Object.assign(p,{name:v.name.trim(),sex:v.sex,birth,death,place:v.place.trim(),bio:v.bio.trim()});logActivity('更新了'+p.name+'的资料：'+v.reason.trim());closeModal();render();toast('人物资料与修改说明已保存')}else{const rel=person(v.relative);if(v.relationship==='father'&&rel.father||v.relationship==='mother'&&rel.mother||v.relationship==='spouse'&&rel.spouse){toast('已有关联人物，请先核对已有关系，避免直接覆盖');return}const p={id:'p'+Date.now(),name:v.name.trim(),sex:v.sex,birth,death,place:v.place.trim(),bio:v.bio.trim(),relation:'家族成员'};if(v.relationship==='child'){if(rel.sex==='M')p.father=rel.id;else p.mother=rel.id}else if(v.relationship==='father')rel.father=p.id;else if(v.relationship==='mother')rel.mother=p.id;else{p.spouse=rel.id;rel.spouse=p.id}data.people.push(p);logActivity('添加了家族人物 '+p.name);closeModal();go('person/'+p.id+'/details');toast('已保存新人物及家庭关系')}
 }else if(f.id==='memory-form'){const v=Object.fromEntries(new FormData(f)),file=$('#memory-file').files[0];if(v.type!=='story'&&!file){toast('请为图像或文稿选择一张图片');return}if(file&&(!file.type.startsWith('image/')||file.size>2*1024*1024)){toast('请选择2MB以内的图片文件');return}let image=file?await readFile(file):null;const m={id:'m'+Date.now(),...v,title:v.title.trim(),desc:v.body.trim().slice(0,55),image};data.memories.unshift(m);if(!save()){data.memories.shift();return}logActivity('添加了家庭记忆《'+m.title+'》');closeModal();state.memoryFilter='all';state.memoryQuery='';go('memories');toast('记忆已保存到当前浏览器')
 }else if(f.id==='note-form'){data.notes.push({person:f.dataset.id,text:$('#note-text').value.trim()});logActivity('为'+person(f.dataset.id).name+'补充了研究笔记');closeModal();render();toast('研究笔记已保存')
 }else if(f.id==='source-form'){data.sources.push({id:'s'+Date.now(),person:f.dataset.id,title:$('#source-title').value.trim(),quote:$('#source-quote').value.trim(),desc:'家庭成员新增的演示资料说明，原件与授权待补充',image:'assets/genealogy.svg',type:'家庭资料',year:'2026'});logActivity('为'+person(f.dataset.id).name+'添加了来源条目');closeModal();render();toast('来源已保存并关联')
 }else if(f.id==='clue-form'){data.notes.push({person:'p3',text:$('#clue-title').value.trim()+'：'+$('#clue-text').value.trim()});logActivity('补充了寻根线索：'+$('#clue-title').value.trim());closeModal();toast('线索已保存为林文海的研究笔记')}
});
document.addEventListener('input',e=>{if(e.target.id==='global-search')$('#global-search-results').innerHTML=searchResults(e.target.value.trim());if(e.target.id==='memory-search'){state.memoryQuery=e.target.value.trim();let ms=data.memories.filter(m=>(state.memoryFilter==='all'||(state.memoryFilter==='saved'?data.favorites.includes(m.id):m.type===state.memoryFilter))&&(m.title+m.desc+person(m.person).name).includes(state.memoryQuery));$('#memory-results').innerHTML=`<div class="memory-grid">${ms.map(memoryCard).join('')}</div>${!ms.length?'<div class="empty-state">没有找到相关记忆。</div>':''}`}});
document.addEventListener('change',async e=>{if(e.target.id==='generations'){state.generations=Number(e.target.value);render()}if(e.target.id==='ocr-file'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>2*1024*1024){toast('请选择2MB以内的图片');return}state.ocrPreview=await readFile(file);render();toast('图片仅供本地预览，下一步仍展示预置样例')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();closeDrawer()}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchDialog()}const dlg=$('.modal')||$('.person-drawer');if(e.key==='Tab'&&dlg){const focusables=$$('button,a[href],input:not([disabled]):not([type=file]),select,textarea,[tabindex="0"]',dlg).filter(el=>el.offsetParent!==null);if(!focusables.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role=button]:not(button)')){e.preventDefault();e.target.click()}});
window.addEventListener('hashchange',router);

// Native mobile interaction layer. Shared data and editing/export flows stay local.
let mobileHistory=[],mobilePath='',mobileBack=false;
state.platform='ios';state.treeView='portrait';state.treeFocus='p0';
function fitDevice(){const w=state.platform==='android'?412:390;const scale=window.innerWidth<=520?1:Math.min(1,Math.max(.5,(window.innerHeight-66)/868));document.documentElement.style.setProperty('--phone-w',w+'px');document.documentElement.style.setProperty('--preview-scale',scale);$('#device')?.classList.toggle('android',state.platform==='android');$('#device')?.classList.toggle('ios',state.platform!=='android');$('#platform-caption').textContent=state.platform==='android'?'Android 应用交互预览':'iOS 应用交互预览';$$('[data-action="mobile-platform"]').forEach(b=>{const active=b.dataset.platform===state.platform;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function mobileBar(title,sub='',back=false,action='search'){return `<header class="app-bar">${back?button(icon('arrow-left'),'mobile-back','m-back','aria-label="返回上一页"'):''}<div class="m-title"><h1>${title}</h1>${sub?`<small>${sub}</small>`:''}</div><div class="m-head-actions">${action?button(icon(action==='search'?'search':action==='export'?'download':action==='invite'?'users':'plus'),action,'m-icon-button',`aria-label="${action==='search'?'搜索家族人物与记忆':action==='export'?'导出资料':action==='invite'?'邀请家人加入':'添加记忆'}"`):''}</div></header>`}
function mobileDemo(){return `<div class="m-demo">体验演示 · 虚构人物与资料</div>`}
function render(){const views={home:homeView,tree:treeView,person:profileView,memories:memoriesView,roots:rootsView,studio:studioView,me:mobileMeView};$('#main').innerHTML=(views[state.route]||homeView)();$('#mobile-nav').innerHTML=`${[['home','home','家园'],['tree','tree','家族树'],['add','plus','记录'],['memories','image','记忆'],['me','user','我的']].map(([route,ic,label])=>route==='add'?`<button class="m-nav-add" data-action="mobile-record" aria-label="记录一段家庭故事"><span>${icon('plus')}</span>记录</button>`:`<a class="m-nav-link ${state.route===route||(route==='tree'&&state.route==='person')?'active':''}" href="#${route}" ${state.route===route?'aria-current="page"':''}>${icon(ic==='home'?'heart':ic)}<span>${label}</span></a>`).join('')}`;fillIcons();fitDevice()}
function router(){const path=location.hash.replace(/^#/,'')||'home';const parts=path.split('/');if(!mobileBack&&mobilePath&&path!==mobilePath&&!(parts[0]==='person'&&mobilePath.split('/')[1]===parts[1]))mobileHistory.push(mobilePath);mobileBack=false;mobilePath=path;state.route=parts[0];if(state.route==='person'){state.person=parts[1]||'p3';state.tab=parts[2]||'details'}closeDrawer();closeModal();render();$('#main').scrollTop=0}
function homeView(){return `<div class="m-page"><header class="app-bar"><div class="m-head-label"><img src="assets/mark.svg" alt="家续标识"><strong>家续</strong></div><div class="m-head-actions">${button(icon('search'),'search','m-icon-button','aria-label="搜索家族人物与记忆"')}${button(icon('bell'),'notifications','m-icon-button','aria-label="家庭动态"')}</div></header><div class="m-body"><div class="m-welcome"><span>知远，今天也留下一点家的记忆。</span><span class="m-tag">${icon('lock')} 家庭空间</span></div><section class="m-home-hero"><div class="m-kicker">OUR FAMILY, OUR STORY</div><h2>每个名字，<br>都有家的故事。</h2><a href="#tree">看看我的家族树 ${icon('arrow-right')}</a><img src="assets/courtyard.svg" alt="闽南古厝原创示意插画"><img class="letter" src="assets/letter.svg" alt="家书示意文稿"></section><div class="m-quick-grid">${[['image','存照片','upload-memory'],['mic','听讲述','interview-route'],['book','识老谱','ocr-route'],['pin','找来处','mobile-roots']].map(([i,t,a])=>`<button class="m-quick" data-action="${a}"><span>${icon(i)}</span>${t}</button>`).join('')}</div><a href="#tree" class="m-card m-family-strip"><span class="m-family-emblem">林</span><div><h3>林氏 · 我们的家</h3><p>${data.people.length} 位家人 · ${data.memories.length} 段记忆 · 4 人共同整理</p></div>${icon('chevron-right')}</a><div class="m-title-row"><h2>家谱里的一点新发现</h2><a href="#studio">去整理 ${icon('chevron-right')}</a></div><button class="m-task-row" data-action="ocr-route" style="width:100%;text-align:left"><span class="m-task-symbol"><img src="assets/genealogy.svg" alt="演示谱页"></span><span><h3>${data.ocrDone?'这一页老谱，已经有了出处':'一页老谱，等你来确认'}</h3><p>${data.ocrDone?'已关联到祖父林文海的资料。':'核对名讳和籍贯，再接回人物档案。'}</p></span>${icon('chevron-right')}</button><div class="m-title-row"><h2>家人留下的记忆</h2><a href="#memories">全部 ${icon('chevron-right')}</a></div><div class="m-home-memories">${data.memories.slice(0,4).map(m=>`<button class="m-home-memory" data-action="memory" data-id="${m.id}">${m.image?`<img src="${m.image}" alt="${esc(m.title)}">`:audioArt()}<div><h4>${esc(m.title)}</h4><small>${esc(m.year)} · ${esc(person(m.person).name)}</small></div></button>`).join('')}</div><section class="m-root-teaser"><img src="assets/mountains.svg" alt="山海原创插画"><h3>山海相望，家脉相连。</h3><p>从一封家书，看看台湾与闽南的家族线索。</p><a href="#roots">走近家人的来处 ${icon('arrow-right')}</a></section>${mobileDemo()}</div></div>`}
function mobilePerson(p,rel){if(!p)return `<button class="m-mobile-person" data-action="add-person" aria-label="补充${rel}"><span class="avatar" style="background:#f1f4e9;color:#b9c7a4">${icon('plus')}</span><strong style="font-size:10px;color:#acb99c">添加家人</strong><span class="m-relation">${rel}</span></button>`;return `<button class="m-mobile-person" data-action="person-drawer" data-id="${p.id}" aria-label="查看${esc(p.name)}人物摘要">${avatar(p)}<strong>${esc(p.name)}</strong><small>${p.birth||'生年待补'}${p.death?'—'+p.death:' · 在世'}</small><span class="m-relation">${rel||esc(p.relation||'家人')}</span></button>`}
function mobilePortrait(){return `<div class="m-tree-portrait"><div class="m-generation-label"><span>父亲的父母</span><span>母亲的父母</span></div><div class="m-grand-row">${[['p3','祖父'],['p4','祖母'],['p5','外祖父'],['p6','外祖母']].map(([id,r])=>mobilePerson(person(id),r)).join('')}</div><div class="m-tree-connector"><svg viewBox="0 0 360 28" preserveAspectRatio="none"><path d="M43 0V13H132V0M88 13V28M228 0V13H317V0M272 13V28"/></svg></div><div class="m-parent-row">${mobilePerson(person('p1'),'父亲')}${mobilePerson(person('p2'),'母亲')}</div><div class="m-tree-connector"><svg viewBox="0 0 360 28" preserveAspectRatio="none"><path d="M88 0V12H272V0M180 12V28"/></svg></div><div class="m-me-row">${mobilePerson(person('p0'),'本人')}</div><div class="m-tree-family">${['p15','p16'].map(id=>`<button class="m-family-pill" data-action="person-drawer" data-id="${id}">${avatar(person(id))}${esc(person(id).name)} · ${esc(person(id).relation)}</button>`).join('')}</div><p class="m-tree-hint">点击家人查看资料，父系和母系共同保留</p></div>`}
function treeView(){return `<div class="m-page">${mobileBar('家族树','林氏家庭 · 从林知远开始',false,'search')}<div class="m-tree-top"><div class="m-segment" aria-label="家族树视图">${[['portrait','tree','祖先图'],['fan','fan','扇形图'],['descendants','list','后代图']].map(([v,i,t])=>`<button class="${state.treeView===v?'active':''}" data-action="tree-view" data-view="${v}" aria-pressed="${state.treeView===v}">${icon(i)}${t}</button>`).join('')}</div><div class="m-tree-context"><span>${icon('lock')} 在世家人仅授权可见</span>${button('人物列表 '+icon('chevron-right'),'search','')}</div></div>${state.treeView==='portrait'?mobilePortrait():state.treeView==='fan'?`<div class="m-fan-container">${fanChart()}</div><p class="m-tree-hint">点击扇区查看人物，了解资料的来处</p>`:`<div class="m-person-list">${descendants()}</div>`}<div class="m-tree-footer">${button(icon('plus')+' 补充一位家人','add-person','')}</div>${mobileDemo()}</div>`}
function showDrawer(id){const p=person(id);state.selected=id;const sc=data.sources.filter(s=>s.person===id).length,mc=data.memories.filter(m=>m.person===id).length;$('#drawer-root').innerHTML=`<div class="drawer-scrim" data-action="close-drawer"></div><section class="person-drawer" role="dialog" aria-modal="true" aria-label="${esc(p.name)}人物摘要"><div class="m-summary-header"><span>${pID(p)} · ${p.death?'历史人物':'家庭授权可见'}</span>${button(icon('close'),'close-drawer','m-icon-button','aria-label="关闭人物摘要"')}</div><div class="m-summary-person">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>${lifespan(p)}</p><span class="m-tag">${esc(p.relation||'家族成员')}${p.style?' · '+esc(p.style):''}</span></div></div><div class="m-summary-info"><div><label>出生地</label>${esc(p.place||'待补充')}</div><div><label>资料</label>${sc} 条来源 · ${mc} 段记忆</div></div><div class="m-summary-actions"><a class="btn btn-primary" href="#person/${p.id}/details">查看人物资料 ${icon('arrow-right')}</a>${button(icon('star')+(data.followed.includes(id)?'已关注':'关注家人'),'follow-person','btn',`data-id="${id}"`)}</div></section>`;$('.person-drawer button').focus()}
function profileView(){const p=person(state.person),sources=data.sources.filter(s=>s.person===p.id),mem=data.memories.filter(m=>m.person===p.id);let body='';if(state.tab==='details')body=`<section class="m-card m-card-pad"><div class="m-card-title"><h2>基本资料</h2>${button(icon('edit')+' 编辑','edit-person','',`data-id="${p.id}" aria-label="编辑人物资料"`)}</div><div class="m-profile-facts">${[['姓名',p.name,'保留原文'],['性别',p.sex==='M'?'男':'女',''],['出生',p.birth+'年',p.place||'地点待补'],['逝世',p.death?p.death+'年':'在世',p.death?'精度：年':'仅授权家人可见'],['祖籍',p.origin||'待补充',''],['字 / 号',p.style||'待补充','']].map(([a,b,c])=>`<div class="m-profile-fact"><label>${a}</label>${esc(b)}${c?`<small>${esc(c)}</small>`:''}</div>`).join('')}</div></section><section class="m-card m-card-pad"><div class="m-card-title"><h2>关于这位家人</h2></div><p class="m-bio">${esc(p.bio||'故事还在整理中，听听家人怎么讲。')}</p></section><section class="m-card m-card-pad"><div class="m-card-title"><h2>家庭成员</h2>${button(icon('plus'),'add-person','','aria-label="补充家庭关系"')}</div>${[p.father,p.mother,p.spouse,...data.people.filter(x=>x.father===p.id||x.mother===p.id).map(x=>x.id)].filter(Boolean).map(id=>`<a class="m-member-row" href="#person/${id}/details">${avatar(person(id))}<span><strong>${esc(person(id).name)}</strong><small>${id===p.father?'父亲':id===p.mother?'母亲':id===p.spouse?'配偶':'子女'} · ${lifespan(person(id))}</small></span>${icon('chevron-right')}</a>`).join('')||'<p class="m-caption">还可以补充父母与其他家人。</p>'}</section><section class="m-card m-card-pad"><div class="m-card-title"><h2>研究笔记</h2>${button(icon('plus'),'add-note','',`data-id="${p.id}" aria-label="添加研究笔记"`)}</div>${data.notes.filter(n=>n.person===p.id).map(n=>`<p class="m-bio">${esc(n.text)}</p>`).join('')||'<p class="m-bio">先记下疑问，找到资料后再确认。</p>'}</section>`;
else if(state.tab==='sources')body=`<div class="m-title-row" style="margin-top:0"><span class="m-caption">每条资料，都能回到原文。</span>${button(icon('plus')+' 添加','add-source','',`data-id="${p.id}"`)}</div>${sources.map(s=>`<article class="m-card"><button class="m-source-row" data-action="source" data-id="${s.id}"><img src="${s.image}" alt="${esc(s.title)}"><div><h3>${esc(s.title)}</h3><p>${esc(s.year)} · ${esc(s.type)} · ${esc(s.person===p.id?'已关联人物':'')}</p></div>${icon('chevron-right')}</button></article>`).join('')||'<div class="m-empty">还没有关联来源，先保存一条原文。</div>'}`;
else if(state.tab==='timeline')body=`<div class="m-card m-card-pad"><div class="m-card-title"><h2>人生时间线</h2><a href="#roots">迁徙线索 ${icon('pin')}</a></div><div class="m-timeline">${(p.id==='p3'?[['1924','出生于福建南安','谱页提供名讳与祖籍线索。','s1'],['约1948','迁居金门的口述线索','年份待核，保留家人的原话。','s3'],['1962','从台南寄出家书','连接两地家人的往来记忆。','s2'],['2003','家人补记的逝世年份','更多出处还可以继续补充。','s3']]:[[p.birth,'出生',p.place||'地点待补',null],[p.death||'现在',p.death?'家人补记':'故事仍在继续',p.bio||'等待补充资料。',null]]).map(([y,t,d,s])=>`<article class="timeline-event"><div class="year">${esc(y)}</div><h4>${esc(t)}</h4><p>${esc(d)}</p>${s?button('查看出处','source','text-link',`data-id="${s}"`):''}</article>`).join('')}</div></div>`;
else if(state.tab==='memories')body=`<div class="m-title-row" style="margin-top:0"><span class="m-caption">与${esc(p.name)}有关的记忆</span>${button(icon('plus')+' 添加','upload-memory','',`data-person="${p.id}"`)}</div><div class="memory-grid">${mem.map(memoryCard).join('')}</div>${!mem.length?'<div class="m-empty">还没有关联记忆，留下一段故事吧。</div>':''}`;
else body=`<section class="m-card m-card-pad"><div class="m-card-title"><h2>家庭编辑记录</h2><span class="m-tag">保留修改理由</span></div>${[...data.activities.map(a=>[a.text,a.time]),['林知远关联了谱页与家书来源','2026年10月23日'],['林建民补充了生平简述','2026年10月21日']].slice(0,8).map(([a,b])=>`<div class="change" style="font-size:12px;color:#8c9e77">${esc(a)}<small style="font-size:9px">${esc(b)}</small></div>`).join('')}</section>`;
return `<div class="m-page"><div class="m-profile-top">${mobileBar('人物资料','',true,null)}<div class="m-profile-person">${avatar(p)}<div><h1>${esc(p.name)}</h1><p>${lifespan(p)} · ${pID(p)}</p></div></div><div class="m-profile-sub"><span class="m-tag">${esc(p.relation||'家族成员')}</span><span class="m-tag">${icon(p.death?'file':'lock')}${p.death?'来源可追溯':'受限可见'}</span>${button(icon('star')+(data.followed.includes(p.id)?'已关注':'关注'),'follow-person','text-link',`data-id="${p.id}" style="margin-left:auto;font-size:11px"`)}</div></div><div class="m-profile-tabs">${[['details','资料',''],['timeline','时间线',''],['sources','来源',sources.length],['memories','记忆',mem.length],['changes','变更','']].map(([v,t,c])=>`<button class="${state.tab===v?'active':''}" data-action="profile-tab" data-tab="${v}">${t}${c!==''?`<small>${c}</small>`:''}</button>`).join('')}</div><div class="m-profile-content">${body}${mobileDemo()}</div></div>`}
function memoriesView(){const mem=data.memories.filter(m=>(state.memoryFilter==='all'||(state.memoryFilter==='saved'?data.favorites.includes(m.id):m.type===state.memoryFilter))&&(!state.memoryQuery||(m.title+m.desc+person(m.person).name).includes(state.memoryQuery)));return `<div class="m-page">${mobileBar('家庭记忆','把生活留下，给家人看',false,'upload-memory')}<div class="m-memory-top"><div class="m-memory-search">${icon('search')}<input id="memory-search" value="${esc(state.memoryQuery)}" placeholder="搜索一段记忆或一位家人" aria-label="搜索家庭记忆"></div><div class="m-filter-row">${[['all','全部'],['image','照片'],['audio','声音'],['story','故事'],['document','文稿'],['saved','收藏']].map(([v,t])=>`<button class="${state.memoryFilter===v?'active':''}" data-action="memory-filter" data-filter="${v}">${t}</button>`).join('')}</div></div><div class="m-body" id="memory-results"><div class="memory-grid">${mem.map(memoryCard).join('')}</div>${!mem.length?'<div class="m-empty">没有找到相关记忆。</div>':''}</div>${mobileDemo()}</div>`}
function rootsView(){return `<div class="m-page">${mobileBar('闽台寻根','从家里的线索，走近家人的来处',true,null)}<div class="m-body"><div class="m-roots-hero"><img src="assets/mountains.svg" alt="山海原创示意插画"><h2>山海相望，<br>家脉相连。</h2><p>台湾与闽南，两地资料一起核对。</p></div><section class="m-card m-card-pad"><div class="m-card-title"><h2>林文海的迁徙线索</h2><span class="m-tag amber">部分年份待核</span></div><div class="m-route-diagram">${[['南安','1924 · 谱页','s1'],['金门','约1948 · 口述','s3'],['台南','1962 · 家书','s2']].map(([t,y,id])=>`<button class="m-route-stop" data-action="source" data-id="${id}"><span>${icon('pin')}</span>${t}<small>${y}</small></button>`).join('')}</div><p class="m-caption" style="margin-bottom:0">点击地点查看依据。路线仅为线索示意，精确年份与行程仍需核对。</p></section><section class="m-card m-card-pad m-root-clue"><span class="m-tag ${data.linked?'':'amber'}">${data.linked?'已保存演示关联':'候选关联 · 待人工核对'}</span><h3>两地谱本中的“林文海”</h3><p>名讳、字“承远”与年代相近。还需要比对父母、房支和原始记载，不能单凭同姓认定亲缘。</p>${button('并排核对两地资料 '+icon('arrow-right'),'compare','m-button')}</section><div class="m-title-row"><h2>家人保存的资料</h2>${button(icon('plus')+' 补充线索','add-clue','')}</div>${data.sources.filter(s=>s.person==='p3').map(s=>`<article class="m-card"><button class="m-source-row" data-action="source" data-id="${s.id}"><img src="${s.image}" alt="${esc(s.title)}"><div><h3>${esc(s.title)}</h3><p>${esc(s.type)} · ${esc(s.year)} · 来源分别保留</p></div>${icon('chevron-right')}</button></article>`).join('')}${mobileDemo()}</div></div>`}
function studioView(){return `<div class="m-page">${mobileBar('AI 整理助手','帮你整理，由家人确认',true,null)}<div class="m-studio-intro ${state.studioMode==='ocr'&&state.ocrStage===2?'compact':''}"><h2>记忆很珍贵，<br>整理可以轻一点。</h2><p>原始资料与整理结果分开保存，每一步都能核对。</p><div class="m-segment" aria-label="AI整理任务">${[['ocr','book','识老谱'],['chat','sparkles','问家事']].map(([v,i,t])=>`<button data-action="studio-mode" data-mode="${v}" class="${state.studioMode===v?'active':''}">${icon(i)}${t}</button>`).join('')}</div></div><div class="m-studio-content">${state.studioMode==='ocr'?ocrContent():state.studioMode==='interview'?interviewContent():chatContent()}${mobileDemo()}</div></div>`}
function ocrContent(){const step=`<div class="stepper"><span class="${state.ocrStage===1?'active':''}"><i>1</i>选谱页</span><b></b><span class="${state.ocrStage===2?'active':''}"><i>2</i>核对</span><b></b><span class="${state.ocrStage===3?'active':''}"><i>3</i>关联</span></div>`;if(state.ocrStage===1)return `${step}<div class="m-ocr-sample"><img src="${state.ocrPreview||'assets/genealogy.svg'}" alt="演示谱页原图"><span class="m-tag">预置样例</span></div><div class="m-sample-info"><div><h3>林氏家谱 · 卷二</h3><p>虚构谱页 · 林文海名讳与籍贯</p></div>${button(icon('image')+' 换图片','ocr-file','')}<input type="file" id="ocr-file" accept="image/*" class="hidden"></div>${button('识别并核对样例 '+icon('arrow-right'),'ocr-run','m-button')}<p class="m-ocr-tip">体验原型使用预置识别结果。其他图片仅供本地预览，不上传服务器。</p>`;
if(state.ocrStage===2)return `${step}<img class="m-review-image" src="assets/genealogy.svg" alt="待核对的原始示意谱页"><div class="m-review-fields">${[['ocr-name','名讳','林文海'],['ocr-style','字 / 号','字承远'],['ocr-birth','出生年份','1924'],['ocr-place','原籍','福建 泉州 南安']].map(([id,l,v])=>`<div class="field"><label for="${id}">${l}${id==='ocr-birth'?'<span class="m-tag amber">请对照原文</span>':''}</label><input id="${id}" value="${v}" ${id==='ocr-birth'?'inputmode="numeric" maxlength="4"':''}></div>`).join('')}</div><p class="m-caption">将关联到已有档案：林文海 JX-0003，不自动新增或合并人物。</p><div class="m-action-dock"><label class="check-row"><input type="checkbox" id="ocr-confirm">我已核对样例原文，同意保存字段与来源。</label>${button('确认，关联到人物 '+icon('check'),'ocr-confirm','m-button')}</div>`;
return `${step}<div class="m-success"><div class="m-success-symbol">${icon('check')}</div><h2>这页记载，<br>已经接回人物档案。</h2><p>原图、核对字段与确认记录已保存。<br>有新的资料时，还可以继续修订。</p><a class="m-button" href="#person/p3/sources">查看人物来源 ${icon('arrow-right')}</a>${button('再整理一页','ocr-back','text-link','style="margin-top:15px"')}</div>`}
function interviewContent(){return `<div class="m-interview-intro"><span class="m-tag">祖母的年节记忆 · 演示访谈</span><h3>“小时候过年，<br>最难忘的是什么？”</h3><button class="m-record-btn ${state.interviewStep===1?'recording':''}" data-action="interview-toggle" aria-label="${state.interviewStep===1?'结束演示访谈':'开始演示访谈'}">${icon(state.interviewStep===1?'pause':'mic')}</button><p>${state.interviewStep===1?'点击结束，整理这一段讲述':'点击开始，听听预置故事的整理过程'}</p></div>${state.interviewStep>=2?`<div class="interview-transcript"><div class="m-card-title"><h2>样例转写</h2>${button(icon('volume')+' 朗读','speak','',`data-id="m3"`)}</div><p>${esc(data.memories.find(m=>m.id==='m3').body)}</p><span class="m-tag">转写样例 · 待家人确认</span></div><div class="interview-transcript"><h4>接着问问</h4><p>家里那时候，是谁写春联？<br>有没有一道每年都会做的年菜？</p>${button('确认，保存为家庭故事','save-interview','m-button')}</div>`:''}<p class="m-ocr-tip">预置流程演示，未启用麦克风。正式产品将保留原音、转写和对应片段。</p>`}
function chatContent(){return `<div class="chat-list" id="chat-list">${state.chat.length?state.chat.map(m=>m.role==='user'?`<div class="chat-question">${esc(m.text)}</div>`:`<div class="chat-answer"><h4>${icon('sparkles')} 依据家庭资料整理</h4><p>${esc(m.text)}</p><div class="chat-citations">${m.sources.map(id=>button(icon('file')+' '+esc(data.sources.find(s=>s.id===id)?.title||'来源资料'),'source','',`data-id="${id}"`)).join('')}</div><div class="m-caption" style="margin-bottom:0">预置问答演示，非实时模型回答</div></div>`).join(''):`<div class="m-success" style="padding-top:25px"><div class="m-success-symbol">${icon('sparkles')}</div><h2>问问家里的资料。</h2><p>从祖父的来处，<br>到一封家书里的牵挂。</p></div>`}</div><div class="suggested-questions">${['林文海从哪里迁到台南？','这封家书记载了什么？','我们和另一本林氏家谱能确认亲缘吗？'].map(q=>button(esc(q),'suggest-question','',`data-question="${esc(q)}"`)).join('')}</div><form id="chat-form" class="m-chat-composer"><input id="chat-question" aria-label="向家庭资料提问" placeholder="问一个关于家人的问题" required maxlength="300"><button type="submit" aria-label="发送问题">${icon('arrow-right')}</button></form><p class="m-caption">只引用授权资料；没有依据时保留疑问。本次使用有限预置样例。</p>`}
function mobileMeView(){return `<div class="m-page">${mobileBar('我的','',false,'invite')}<div class="m-body"><div class="m-account-hero">${avatar(person('p0'))}<div><h2>林知远</h2><p>林氏家庭空间 · 家庭管理员</p></div></div><div class="m-account-stats"><div><strong>${data.people.length}</strong><span>位家人</span></div><div><strong>${data.memories.length}</strong><span>段记忆</span></div><div><strong>${data.favorites.length}</strong><span>个收藏</span></div></div><section class="m-card">${[['users','家庭成员与邀请','members'],['star','我的收藏','mobile-favorites'],['file','资料备份与导出','export'],['clock','家里的新动态','notifications']].map(([i,t,a])=>`<button class="m-setting-row" data-action="${a}">${icon(i)}${t}${icon('chevron-right')}</button>`).join('')}</section><section class="m-card">${[['help','体验指引','guide'],['shield','隐私与演示说明','about'],['history','恢复初始演示','reset-dialog']].map(([i,t,a])=>`<button class="m-setting-row" data-action="${a}">${icon(i)}${t}${icon('chevron-right')}</button>`).join('')}</section><div class="m-privacy-card"><h3>${icon('lock')} 把家人的资料，好好保存。</h3><p>在世人物与家庭记忆默认仅授权可见。当前为浏览器本地演示，不连接正式账号和云端服务。</p></div>${mobileDemo()}</div></div>`}
function guide(){modal('像使用一款手机应用一样体验',`<p class="modal-description">底部切换页面，中间“记录”随手保存照片与故事。所有资料都是虚构样例。</p><div class="m-howto">${[['01','浏览竖屏家族树','tree'],['02','查看林文海的人物资料','person/p3/details'],['03','识别并核对一页老谱','studio'],['04','核对闽台两地谱本','roots'],['05','保存和收藏家庭记忆','memories'],['06','导出当前演示资料','me']].map(([n,t,r])=>`<a href="#${r}"><span>${n}</span>${t}${icon('chevron-right')}</a>`).join('')}</div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='mobile-platform'){state.platform=el.dataset.platform;fitDevice()}else if(a==='mobile-back'){mobileBack=true;const p=mobileHistory.pop()||'home';go(p)}else if(a==='mobile-roots')go('roots');else if(a==='mobile-favorites'){state.memoryFilter='saved';state.memoryQuery='';go('memories')}else if(a==='mobile-record'){modal('留下一点家的记忆',`<p class="modal-description">从一张照片、一段讲述，或一个名字开始。</p><div class="m-record-options">${[['image','保存照片','照片、家书与文稿','upload-memory'],['mic','讲一段故事','口述史与家庭访谈','mobile-interview'],['book','整理老谱','识别、核对、关联','mobile-ocr'],['users','添加家人','从已知关系开始','add-person']].map(([i,t,s,a])=>`<button class="m-record-option" data-action="${a}">${icon(i)}<strong>${t}</strong><small>${s}</small></button>`).join('')}</div>`)}else if(a==='mobile-interview'){closeModal();state.studioMode='interview';go('studio')}else if(a==='mobile-ocr'){closeModal();state.studioMode='ocr';go('studio')}});
window.addEventListener('resize',fitDevice);

// V3: person-centred genealogy workflows. All records and operations stay local.
const byId=id=>data.people.find(p=>p.id===id);
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
const norm=s=>String(s||'').replace(/[遠華蘭黃陳吳鄭臺灣國慶譜縣莊門東義]/g,c=>({'遠':'远','華':'华','蘭':'兰','黃':'黄','陳':'陈','吳':'吴','鄭':'郑','臺':'台','灣':'湾','國':'国','慶':'庆','譜':'谱','縣':'县','莊':'庄','門':'门','東':'东','義':'义'}[c])).replace(/[\s·，。、]/g,'');
const kinTypes=['亲生','收养','过继','继亲','待考'];
const catalog=[
 {id:'r1',title:'南安林氏续谱 · 卷三第12页',type:'谱牒',year:'1936',name:'林文海',birth:'1924',death:'2003',place:'福建 泉州 南安',origin:'福建 南安',style:'字承遠',father:'林宗源',mother:'黃秀英',quote:'文海，字承遠，宗源之子。原居泉州南安。',image:'assets/genealogy.svg',target:'p3'},
 {id:'r2',title:'台南寄南安家书 · 第1页',type:'家书',year:'1962',name:'林文海',birth:'',place:'台湾 台南（通信地点）',origin:'福建 南安',style:'承遠',father:'',mother:'',quote:'家人平安，見字如面。每逢佳節，念及故里。',image:'assets/letter.svg',target:'p3'},
 {id:'r3',title:'台南林氏家藏补记 · 第6页',type:'家藏补记',year:'1978',name:'林文海',birth:'1924',place:'台湾 台南',origin:'泉州南安',style:'字承遠',father:'林宗源',mother:'黃秀英',quote:'原籍南安，父宗源，母黃氏。台南家人补记。',image:'assets/genealogy.svg',target:'p3'},
 {id:'r4',title:'同名人物对照谱 · 第27页',type:'谱牒',year:'1940',name:'林文海',birth:'1918',place:'福建 漳州',origin:'福建 漳州',style:'字景明',father:'林瑞成',mother:'李氏',quote:'文海，字景明，瑞成之子。此为同名异人演示。',image:'assets/genealogy.svg',target:'p3'}
];
function initCore(){
 if(data.coreVersion===3)return;
 data.parentGroups=data.people.filter(p=>p.father||p.mother).map(p=>({id:'pg-'+p.id,child:p.id,father:p.father||'',mother:p.mother||'',type:'亲生',reason:'家庭样例关系',source:''}));
 data.unions=[];data.people.forEach(p=>{if(p.spouse&&!data.unions.some(u=>u.partners.includes(p.id)&&u.partners.includes(p.spouse)))data.unions.push({id:'u-'+p.id,partners:[p.id,p.spouse],status:'婚姻',date:'',place:'',reason:'家庭样例关系'})});
 data.preferredParents={};data.china={p7:{originalName:'林宗源',generation:'17',generationChar:'宗',branch:'na',hall:'南安林氏家堂（示例）'},p3:{originalName:'林文海',genealogyName:'文海',courtesy:'承遠',generation:'18',generationChar:'文',branch:'tn',hall:'南安林氏家堂（示例）',rank:'长子',dateOriginal:'甲子年生（家藏记载）',calendar:'干支原文',placeOriginal:'泉州南安',placeModern:'福建省泉州市南安市',placeStatus:'县级候选，村里待核',source:'s1'},p1:{originalName:'林建民',generation:'19',generationChar:'建',branch:'tn'},p0:{originalName:'林知遠',generation:'20',generationChar:'知',branch:'xm'},p16:{generation:'21',generationChar:'沐',branch:'xm'}};
 data.clan={surname:'林',hall:'南安林氏家堂（示例）',poem:'宗 文 建 知 沐',start:17,branches:[{id:'na',name:'南安祖籍支',founder:'p7',place:'福建南安'},{id:'tn',name:'台南支系',founder:'p3',place:'台湾台南'},{id:'xm',name:'厦门家庭支',founder:'p0',place:'福建厦门'}]};
 if(!byId('p17'))data.people.push({id:'p17',name:'林文海',sex:'M',birth:'1924',death:'2003',place:'泉州南安',origin:'福建 南安',style:'字承遠',relation:'待核重复档案',bio:'由另一份家庭摘录建立的候选重复人物，需核对后处理。'});
 data.china.p17={originalName:'林文海',courtesy:'承遠',generation:'18',generationChar:'文',branch:'tn'};
 data.recordDecisions={};data.duplicateDecisions={};data.revisions=[];data.coreVersion=3;save();
}
initCore();
state.treeFocus='p0';state.generations=3;state.zoom=1;state.fanMode='default';state.taskFilter='all';state.searchMode='people';state.searchText='';state.treeRecent=['p0'];state.descClosed=[];
function groups(id){return (data.parentGroups||[]).filter(g=>g.child===id)}
function parents(id){const a=groups(id);return a.find(g=>g.id===data.preferredParents?.[id])||a.find(g=>g.type==='亲生')||a[0]||{father:'',mother:'',type:'亲生'}}
function partners(id){return (data.unions||[]).filter(u=>u.partners.includes(id))}
function children(id){return [...new Set((data.parentGroups||[]).filter(g=>g.father===id||g.mother===id).map(g=>g.child))].map(byId).filter(Boolean)}
function branchName(id){return data.clan.branches.find(b=>b.id===data.china[id]?.branch)?.name||'房支待考'}
function sourceCount(id){return data.sources.filter(s=>s.person===id).length}
function duplicateCandidates(id){const p=byId(id);return data.people.filter(q=>q.id!==id&&q.death&&p?.death&&norm(q.name)===norm(p.name)&&!data.duplicateDecisions[[id,q.id].sort().join(':')])}
function openTasks(){return catalog.filter(r=>!data.recordDecisions[r.id]).length+duplicateCandidates('p3').length+(data.ocrDone?0:1)+(data.linked?0:1)}
function corePayload(){const {revisions,activities,...rest}=data;return structuredClone(rest)}
function commitCore(id,title,reason,fn){const before=corePayload();fn();const rev={id:uid('rv'),person:id,title,reason,time:new Date().toLocaleString('zh-CN',{hour12:false}),before,after:JSON.stringify(corePayload())};data.revisions.unshift(rev);data.revisions=data.revisions.slice(0,10);logActivity(title+'：'+reason);save();return rev}
function undoCore(){const r=data.revisions[0];if(!r||JSON.stringify(corePayload())!==r.after){toast('已有后续资料变更，请先核对当前记录，不能直接撤销');return}const history=data.revisions.slice(1),activity=data.activities;data={...structuredClone(r.before),revisions:history,activities:activity};logActivity('撤销了最近修改：'+r.title);closeModal();if(!byId(state.person))state.person='p3';render();toast('已恢复修改前的人物、关系与来源')}
function syncParents(id){const p=byId(id),g=parents(id);if(p){p.father=g.father||'';p.mother=g.mother||''}}
function ancestorOf(a,b,visited=new Set()){if(a===b)return true;if(visited.has(b))return false;visited.add(b);return groups(b).some(g=>[g.father,g.mother].filter(Boolean).some(id=>ancestorOf(a,id,visited)))}
function validateParentEdge(child,parent){if(ancestorOf(child,parent))throw Error('该关系会形成祖先循环，请重新核对');if(partners(child).some(u=>u.partners.includes(parent)))throw Error('该人物已是配偶，不能同时直接登记为父母');const c=byId(child),p=byId(parent);if(/^\d+$/.test(c?.birth||'')&&/^\d+$/.test(p?.birth||'')&&Number(p.birth)>=Number(c.birth))throw Error('父母出生年份不早于子女，请先核对年代');}
function relationPath(target){const queue=[{id:'p0',nodes:['p0'],edges:[]}],seen=new Set(['p0']);while(queue.length){const c=queue.shift();if(c.id===target)return c;const links=[];groups(c.id).forEach(g=>{if(g.father)links.push([g.father,(g.type==='亲生'?'':g.type+'·')+'父亲']);if(g.mother)links.push([g.mother,(g.type==='亲生'?'':g.type+'·')+'母亲'])});partners(c.id).forEach(u=>u.partners.filter(id=>id!==c.id).forEach(id=>links.push([id,'配偶'])));children(c.id).forEach(p=>{const g=groups(p.id).find(g=>g.father===c.id||g.mother===c.id);links.push([p.id,(g.type==='亲生'?'':g.type+'·')+(p.sex==='F'?'女儿':'儿子')])});for(const [id,label] of links){if(!seen.has(id)&&byId(id)){seen.add(id);queue.push({id,nodes:[...c.nodes,id],edges:[...c.edges,label]})}}}return null}
function showRelationship(id){const path=relationPath(id);modal('与我的关系',path?`<p class="modal-description">按当前已录入的家庭关系计算，包含关系类型。</p><div class="x-kin-path">${path.nodes.map((id,i)=>`${i?`<span class="x-path-edge">${icon('chevron-down')}${esc(path.edges[i-1])}</span>`:''}<a href="#person/${id}/details">${avatar(byId(id))}<span>${esc(byId(id).name)}<small>${pID(byId(id))}</small></span></a>`).join('')}</div>`:'<div class="x-notice">目前没有可验证的关系路径。先补充父母、配偶或子女关系，不能仅凭同姓接谱。</div>')}
function coreFocus(id){if(!byId(id))return;state.treeFocus=id;state.zoom=1;state.treeRecent=[id,...state.treeRecent.filter(x=>x!==id)].slice(0,8);closeDrawer();go('tree')}
function render(){initCore();const views={home:homeView,tree:treeView,person:profileView,memories:memoriesView,roots:rootsView,studio:studioView,me:mobileMeView,tasks:tasksView,search:searchView,clan:clanView};$('#main').innerHTML=(views[state.route]||homeView)();$('#mobile-nav').innerHTML=[['tree','tree','家族树'],['tasks','check','待办'],['memories','image','记忆'],['home','pin','发现'],['me','list','更多']].map(([r,i,t])=>`<a href="#${r}" class="m-nav-link ${state.route===r||(r==='tree'&&state.route==='person')||(r==='home'&&['roots','clan','studio'].includes(state.route))?'active':''}" ${state.route===r?'aria-current="page"':''}>${icon(i)}<span>${t}${r==='tasks'&&openTasks()?'<i class="x-nav-dot"></i>':''}</span></a>`).join('');fillIcons();fitDevice();if(state.route==='tree')bindCoreTree()}
function router(){initCore();const path=location.hash.replace(/^#/,'')||'tree',parts=path.split('/');if(!mobileBack&&mobilePath&&path!==mobilePath)mobileHistory.push(mobilePath);mobileBack=false;mobilePath=path;state.route=parts[0];if(state.route==='person'){state.person=byId(parts[1])?parts[1]:'p3';state.tab=parts[2]||'details'}closeDrawer();closeModal();render();$('#main').scrollTop=0}
function coreHeader(title,sub='',back=false,actions=''){return `<header class="app-bar x-app-bar">${back?button(icon('arrow-left'),'mobile-back','m-back','aria-label="返回上一页"'):''}<div class="m-title"><h1>${title}</h1>${sub?`<small>${sub}</small>`:''}</div><div class="m-head-actions">${actions||button(icon('search'),'search','m-icon-button','aria-label="搜索人物或资料"')}</div></header>`}
function treeView(){const p=byId(state.treeFocus)||byId('p0'),g=parents(p.id);return `<div class="m-page x-tree-page">${coreHeader('家族树',esc(p.name)+' · '+pID(p),false,button(icon('history'),'x-tree-history','m-icon-button','aria-label="最近浏览人物"')+button(icon('search'),'search','m-icon-button','aria-label="搜索人物或资料"'))}<div class="x-tree-toolbar"><div class="m-segment">${[['portrait','tree','祖先图'],['fan','fan','扇形图'],['descendants','list','后代图']].map(([v,i,t])=>button(icon(i)+t,'tree-view',state.treeView===v?'active':'',`data-view="${v}" aria-pressed="${state.treeView===v}"`)).join('')}</div><div class="x-tree-options"><button data-action="x-tree-home">${icon('focus')}回到本人</button><select id="x-generations" aria-label="显示代数">${[3,4,5].map(n=>`<option value="${n}" ${state.generations===n?'selected':''}>${n}代</option>`).join('')}</select><button data-action="x-branches">${icon('branch')}房支</button>${groups(p.id).length>1?button(g.type+'父母 '+icon('chevron-down'),'x-parent-choice','',`data-id="${p.id}"`):''}</div></div>${state.treeView==='portrait'?corePortrait(p):state.treeView==='fan'?coreFan(p):coreDescendants(p)}<div class="x-tree-status"><span>${icon('lock')}在世人物受限可见</span><button data-action="x-rel-start" data-id="${p.id}" data-kind="child">${icon('plus')}添加家人</button></div></div>`}
function treeLevels(root,n){const rows=[[{p:root}]];for(let depth=1;depth<n;depth++){const row=[];rows[depth-1].forEach(node=>{const g=node.p?parents(node.p.id):{};row.push({p:byId(g.father),child:node.p?.id,kind:'father',group:g.id},{p:byId(g.mother),child:node.p?.id,kind:'mother',group:g.id})});rows.push(row)}return rows}
function corePortrait(root){const rows=treeLevels(root,state.generations),w=Math.max(356,2**(state.generations-1)*88),h=state.generations*137+40,card=76;let nodes='',lines='';rows.forEach((row,d)=>row.forEach((node,i)=>{const x=(i+.5)*w/row.length-card/2,y=(state.generations-1-d)*137+32;if(d<rows.length-1){for(let k=0;k<2;k++){const px=(i*2+k+.5)*w/(row.length*2),py=y-137+96;lines+=`<path d="M${x+card/2} ${y}V${y-20}H${px}V${py}"/>`}}if(node.p){const p=node.p,hasParents=groups(p.id).some(g=>g.father||g.mother);nodes+=`<div class="x-tree-node ${p.sex==='F'?'female':''} ${p.id===root.id?'centre':''}" style="left:${x}px;top:${y}px;width:${card}px">${hasParents?button(icon('chevron-down'),'x-focus','x-expand',`data-id="${p.id}" aria-label="展开${esc(p.name)}的祖先"`):''}<button class="x-node-hit" data-action="person-drawer" data-id="${p.id}" aria-label="查看${esc(p.name)}人物摘要">${avatar(p)}<strong>${esc(p.name)}</strong><small>${esc(p.birth||'?')}–${p.death?esc(p.death):'在世'}</small><span>${p.id===root.id?'中心人物':data.china[p.id]?.generation?data.china[p.id].generation+'世':pID(p)}</span></button>${sourceCount(p.id)?`<i class="x-node-source">${icon('file')}</i>`:''}</div>`}else if(node.child)nodes+=`<button class="x-tree-empty" style="left:${x}px;top:${y}px;width:${card}px" data-action="x-rel-start" data-id="${node.child}" data-kind="${node.kind}" data-group="${node.group||''}" aria-label="为${esc(byId(node.child).name)}添加${node.kind==='father'?'父亲':'母亲'}">${icon('plus')}<span>添加${node.kind==='father'?'父亲':'母亲'}</span></button>`}));return `<div class="x-tree-viewport" id="x-tree-viewport"><div id="x-tree-size" style="width:${w*state.zoom}px;height:${h*state.zoom}px"><div id="x-tree-surface" style="width:${w}px;height:${h}px;transform:scale(${state.zoom})"><svg class="x-tree-lines" width="${w}" height="${h}">${lines}</svg>${nodes}</div></div></div><div class="x-zoom-controls">${button(icon('minus'),'x-zoom-out','','aria-label="缩小家族树"')}<span>${Math.round(state.zoom*100)}%</span>${button(icon('plus'),'x-zoom-in','','aria-label="放大家族树"')}${button(icon('focus'),'x-centre','','aria-label="居中当前家族树"')}</div><div class="x-tree-tip">拖动查看 · 双指或按钮缩放 · 点击上箭头接续祖先</div>`}
function bindCoreTree(){const box=$('#x-tree-viewport');if(!box)return;box.scrollLeft=Math.max(0,(box.scrollWidth-box.clientWidth)/2);box.scrollTop=Math.max(0,box.scrollHeight-box.clientHeight);const pts=new Map();let start=null,pinch=null;box.addEventListener('pointerdown',e=>{pts.set(e.pointerId,[e.clientX,e.clientY]);start={x:e.clientX,y:e.clientY,sx:box.scrollLeft,sy:box.scrollTop};if(pts.size===2){const [a,b]=[...pts.values()];pinch={dist:Math.hypot(a[0]-b[0],a[1]-b[1]),zoom:state.zoom}}});box.addEventListener('pointermove',e=>{if(!pts.has(e.pointerId))return;pts.set(e.pointerId,[e.clientX,e.clientY]);if(pts.size===2&&pinch){const[a,b]=[...pts.values()];const z=Math.max(.55,Math.min(1.6,pinch.zoom*Math.hypot(a[0]-b[0],a[1]-b[1])/pinch.dist));setTreeZoom(z,false);state.dragBlock=Date.now()+300}else if(start){const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>7){box.scrollLeft=start.sx-dx;box.scrollTop=start.sy-dy;state.dragBlock=Date.now()+300;box.setPointerCapture(e.pointerId)}}});for(const event of ['pointerup','pointercancel'])box.addEventListener(event,e=>{pts.delete(e.pointerId);start=null;pinch=null});box.addEventListener('click',e=>{if(state.dragBlock>Date.now()){e.preventDefault();e.stopImmediatePropagation()}},true)}
function setTreeZoom(z,centre=true){state.zoom=Math.round(Math.max(.55,Math.min(1.6,z))*100)/100;const s=$('#x-tree-surface'),b=$('#x-tree-viewport');if(s){const ratio=state.zoom/(parseFloat(s.style.transform.slice(6))||1);const cx=b.scrollLeft+b.clientWidth/2,cy=b.scrollTop+b.clientHeight/2;s.style.transform=`scale(${state.zoom})`;$('#x-tree-size').style.width=parseFloat(s.style.width)*state.zoom+'px';$('#x-tree-size').style.height=parseFloat(s.style.height)*state.zoom+'px';if(centre){b.scrollLeft=cx*ratio-b.clientWidth/2;b.scrollTop=cy*ratio-b.clientHeight/2}$('.x-zoom-controls span').textContent=Math.round(state.zoom*100)+'%'}}
function coreFan(root){const rows=treeLevels(root,Math.min(5,state.generations)),colours=['#f3c65a','#7ec3db','#d4a9d8','#acd19d','#f3aa88'],polar=(r,a)=>[320+r*Math.cos(a*Math.PI/180),324+r*Math.sin(a*Math.PI/180)];let shapes='';rows.slice(1).forEach((row,d)=>row.forEach((n,i)=>{const a=-180+i*180/row.length,b=a+180/row.length,r1=43+d*63,r2=r1+61,p1=polar(r2,a),p2=polar(r2,b),p3=polar(r1,b),p4=polar(r1,a),t=polar((r1+r2)/2,(a+b)/2),cn=n.p?data.china[n.p.id]:{};let fill=colours[d%colours.length];if(state.fanMode==='sources')fill=n.p?(sourceCount(n.p.id)?'#9cc7a8':'#e4e7ea'):'#f2f3f4';if(state.fanMode==='branch')fill=cn?.branch?colours[data.clan.branches.findIndex(x=>x.id===cn.branch)%5]:'#e4e7ea';if(state.fanMode==='country')fill=n.p?(n.p.place?.includes('台湾')?'#78bcda':'#efc35e'):'#f1f2f3';if(!n.p)fill='#f0f1f2';shapes+=`<g ${n.p?`data-action="person-drawer" data-id="${n.p.id}" role="button" tabindex="0" aria-label="查看${esc(n.p.name)}人物摘要"`:''}><path d="M${p1}A${r2} ${r2} 0 0 1 ${p2}L${p3}A${r1} ${r1} 0 0 0 ${p4}Z" fill="${fill}" stroke="white" stroke-width="1.5"/>${n.p?`<text x="${t[0]}" y="${t[1]}" text-anchor="middle" font-size="${d>2?10:13}" fill="#26343c">${esc(n.p.name)}</text>`:''}</g>`}));return `<div class="x-fan"><svg viewBox="${320-(104+(Math.min(5,state.generations)-2)*63)-10} ${324-(104+(Math.min(5,state.generations)-2)*63)-10} ${(104+(Math.min(5,state.generations)-2)*63)*2+20} ${(104+(Math.min(5,state.generations)-2)*63)+70}" aria-label="以${esc(root.name)}为中心的${state.generations}代扇形图">${shapes}<circle cx="320" cy="324" r="41" fill="#087e93" data-action="person-drawer" data-id="${root.id}"/><text x="320" y="324" text-anchor="middle" fill="white" font-size="15">${esc(root.name)}</text></svg></div><div class="x-fan-filters">${[['default','世代'],['country','出生地'],['sources','来源覆盖'],['branch','房支']].map(([v,t])=>button(t,'x-fan-filter',state.fanMode===v?'active':'',`data-mode="${v}"`)).join('')}</div><p class="x-fan-legend">${state.fanMode==='sources'?'绿色：已有来源　灰色：待补来源':state.fanMode==='country'?'金色：福建等地　蓝色：台湾　灰色：未记录':state.fanMode==='branch'?'颜色按已记录房支分组；未确认者显示灰色':'点击扇区查看人物资料；空白代表尚未录入'}</p><button class="x-wide-link" data-action="x-person-open" data-id="${root.id}">查看${esc(root.name)}资料 ${icon('chevron-right')}</button>`}
function coreDescendants(root){function row(p,d,seen){if(d>6||seen.has(p.id))return '';const next=new Set([...seen,p.id]),kids=children(p.id),closed=state.descClosed.includes(p.id);return `<div class="x-desc-node" style="margin-left:${Math.min(d*15,75)}px"><div>${kids.length?button(icon(closed?'plus':'minus'),'x-desc-toggle','x-desc-toggle',`data-id="${p.id}" aria-label="${closed?'展开':'折叠'}${esc(p.name)}的后代"`):'<span class="x-desc-dot"></span>'}<button class="x-person-inline" data-action="person-drawer" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${lifespan(p)}</small></span>${kids.length?`<em>${kids.length}位子女</em>`:''}</button></div></div>${closed?'':kids.map(k=>row(k,d+1,next)).join('')}`};return `<div class="x-desc-list"><p class="x-muted">${esc(root.name)}的已录入后代 · 点击 ± 展开或折叠</p>${row(root,0,new Set())}${!children(root.id).length?'<div class="x-notice">尚无子女记录，可从家庭页继续补充。</div>':''}</div>`}
function showDrawer(id){if(state.dragBlock>Date.now()||!byId(id))return;state.selected=id;const p=byId(id);$('#drawer-root').innerHTML=`<div class="drawer-scrim" data-action="close-drawer"></div><section class="person-drawer x-person-sheet" role="dialog" aria-modal="true" aria-label="${esc(p.name)}人物摘要"><div class="m-summary-header"><span>${pID(p)} · ${p.death?'历史人物':'受限可见'}</span>${button(icon('close'),'close-drawer','m-icon-button','aria-label="关闭人物摘要"')}</div><div class="m-summary-person">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>${lifespan(p)}</p><span>${esc(p.place||'地点待补')}</span></div></div><div class="x-summary-metrics"><span>${sourceCount(id)}条来源</span><span>${data.memories.filter(m=>m.person===id).length}段记忆</span><span>${esc(branchName(id))}</span></div><div class="x-summary-buttons"><a class="btn btn-primary" href="#person/${id}/details">${icon('user')}人物资料</a>${button(icon('tree')+'查看此人的树','x-focus','btn',`data-id="${id}"`)}</div><div class="x-sheet-links">${button(icon('users')+'家庭成员','x-family-open','',`data-id="${id}"`)}${button(icon('branch')+'与我的关系','x-relationship','',`data-id="${id}"`)}${button(icon('edit')+'编辑资料','edit-person','',`data-id="${id}"`)}</div></section>`;$('.person-drawer button').focus()}
function personRow(p,sub='',end=''){return `<div class="x-member"><a href="#person/${p.id}/details">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${sub||lifespan(p)}</small><small>${pID(p)}</small></span></a>${end}</div>`}
function profileView(){const p=byId(state.person)||byId('p3'),id=p.id,c=data.china[id]||{},sources=data.sources.filter(s=>s.person===id),mem=data.memories.filter(m=>m.person===id);let body='';
 if(state.tab==='details')body=`${duplicateCandidates(id).length?`<button class="x-alert" data-action="x-duplicates" data-id="${id}">${icon('users')}可能存在重复人物<span>核对 ${icon('chevron-right')}</span></button>`:''}<section class="x-section"><div class="x-section-head"><h2>重要资料</h2>${button(icon('edit')+'编辑','edit-person','',`data-id="${id}"`)}</div><div class="x-facts">${[['姓名',p.name,'原文：'+(c.originalName||p.name)],['性别',p.sex==='M'?'男':'女',''],['出生',p.birth||'待补充',p.place||'地点待补充'],['逝世',p.death||'在世',p.death?'精度：年':'仅授权家人可见']].map(([l,v,d])=>`<div><label>${l}</label><strong>${esc(v)}</strong><small>${esc(d)}</small></div>`).join('')}</div></section><section class="x-section"><div class="x-section-head"><h2>其他资料 · 中国族谱</h2>${button(icon('edit')+'编辑','x-china-edit','',`data-id="${id}"`)}</div><div class="x-fact-list">${[['谱名 / 字 / 号',[c.genealogyName,c.courtesy,c.artName].filter(Boolean).join(' / ')||p.style||'待补'],['世次 / 字辈',[c.generation?c.generation+'世':'',c.generationChar?'派字「'+c.generationChar+'」':''].filter(Boolean).join(' · ')||'待考'],['房支 / 堂号',branchName(id)+(c.hall?' · '+c.hall:'')],['生辰原文',c.dateOriginal||'待补，保留农历与年号原文'],['祖籍原文',c.placeOriginal||p.origin||'待补'],['现代地名候选',c.placeModern||'待核对']].map(([l,v])=>`<div><label>${l}</label><span>${esc(v)}</span></div>`).join('')}</div><div class="x-inline-links"><a href="#clan">字辈与房支 ${icon('chevron-right')}</a>${button('古今地名核对','x-place-edit','',`data-id="${id}"`)}</div></section><section class="x-section"><div class="x-section-head"><h2>生平简述</h2>${button(icon('edit'),'edit-person','',`data-id="${id}" aria-label="编辑生平简述"`)}</div><p class="x-paragraph">${esc(p.bio||'还没有生平简述，等待家人补充。')}</p></section><section class="x-section"><div class="x-section-head"><h2>研究帮助</h2><a href="#tasks">查看待办</a></div>${id==='p3'?`<button class="x-wide-link" data-action="x-record-compare" data-record="r1" data-id="${id}">${icon('file')}核对一条谱牒资料提示 ${icon('chevron-right')}</button>`:button(icon('search')+'检索历史资料','x-record-search','x-wide-link')}<button class="x-wide-link" data-action="x-relationship" data-id="${id}">${icon('branch')}与我的关系 ${icon('chevron-right')}</button><button class="x-wide-link" data-action="x-duplicates" data-id="${id}">${icon('users')}查找可能重复人物 ${icon('chevron-right')}</button></section>`;
 else if(state.tab==='family'||state.tab==='parents'||state.tab==='spouses')body=familyContent(p);
 else if(state.tab==='sources')body=`<div class="x-section-head x-body-head"><h2>来源 ${sources.length}</h2>${button(icon('plus')+'添加来源','x-source-add','',`data-id="${id}"`)}</div><p class="x-muted">原图与摘录分别保留，关联不代表所有事实都已证实。</p>${sources.map(s=>`<article class="x-source-card"><button data-action="source" data-id="${s.id}"><img src="${s.image||'assets/genealogy.svg'}" alt="${esc(s.title)}"><span><strong>${esc(s.title)}</strong><small>${esc(s.year)} · ${esc(s.type)}</small><small>${esc(s.desc)}</small></span>${icon('chevron-right')}</button><div>${button('查看原文','source','',`data-id="${s.id}"`)}${button('解除关联','x-source-unlink','',`data-id="${s.id}"`)}</div></article>`).join('')||'<div class="x-notice">暂无来源。可检索样例资料，逐项核对后关联。</div>'}`;
 else if(state.tab==='memories')body=`<div class="x-section-head x-body-head"><h2>人物记忆 ${mem.length}</h2>${button(icon('plus')+'添加','upload-memory','',`data-person="${id}"`)}</div><div class="memory-grid">${mem.map(memoryCard).join('')}</div>${!mem.length?'<div class="x-notice">尚未添加这位人物的照片、文稿或声音。</div>':''}`;
 else if(state.tab==='changes')body=`<section class="x-section"><div class="x-section-head"><h2>修改记录</h2></div>${data.revisions.filter(r=>r.person===id||r.person==='clan').map(r=>`<article class="x-revision"><strong>${esc(r.title)}</strong><p>${esc(r.reason)}</p><small>林知远 · ${esc(r.time)}</small>${data.revisions[0]===r?button('查看并撤销最近修改','x-undo-dialog','',`data-id="${r.id}"`):''}</article>`).join('')||'<p class="x-paragraph">暂无本次体验的修改记录。</p>'}</section><section class="x-section"><h2>研究笔记</h2>${data.notes.filter(n=>n.person===id).map(n=>`<p class="x-paragraph">${esc(n.text)}</p>`).join('')}${button(icon('plus')+'添加研究笔记','add-note','x-wide-link',`data-id="${id}"`)}</section>`;
 else body=`<section class="x-section"><h2>人生时间线</h2><div class="m-timeline">${[[p.birth||'待补','出生',p.place||'地点待补'],...(id==='p3'?[['约1948','金门迁居线索','口述记载，年份待核'],['1962','台南家书','通信地点，不能等同于出生地']]:[]),[p.death||'至今',p.death?'逝世':'在世',p.death?'家人补记，具体日期待核':'受限可见']].map(([y,t,d])=>`<article class="timeline-event"><div class="year">${esc(y)}</div><h4>${t}</h4><p>${esc(d)}</p></article>`).join('')}</div><a class="x-wide-link" href="#roots">闽台迁徙线索 ${icon('chevron-right')}</a></section>`;
 return `<div class="m-page x-profile-page">${coreHeader('人物资料','',true,button(icon('tree'),'x-focus','m-icon-button',`data-id="${id}" aria-label="查看此人的树"`)+button(icon('settings'),'x-person-tools','m-icon-button',`data-id="${id}" aria-label="人物工具"`))}<div class="x-profile-banner">${avatar(p)}<div><h1>${esc(p.name)}</h1><p>${lifespan(p)}</p><small>${pID(p)} · ${p.death?'历史人物':'受限可见'}</small></div>${button(icon('star'),'follow-person','x-follow',`data-id="${id}" aria-label="${data.followed.includes(id)?'取消关注':'关注'}${esc(p.name)}"`)}</div><div class="x-profile-shortcuts">${button(icon('tree')+'查看此人的树','x-focus','',`data-id="${id}"`)}${button(icon('branch')+'与我的关系','x-relationship','',`data-id="${id}"`)}</div><div class="m-profile-tabs x-profile-tabs">${[['details','详情'],['family','家庭'],['sources','来源 '+sources.length],['memories','记忆 '+mem.length],['timeline','时间线'],['changes','变更']].map(([v,t])=>button(t,'profile-tab',state.tab===v?'active':'',`data-tab="${v}"`)).join('')}</div><div class="x-profile-body">${body}${mobileDemo()}</div></div>`}
function familyContent(p){const gs=groups(p.id),us=partners(p.id),allKids=children(p.id);const parentBlocks=gs.map(g=>`<section class="x-section"><div class="x-section-head"><h2>${esc(g.type)}父母</h2>${button(icon('edit'),'x-parent-edit','',`data-group="${g.id}" aria-label="编辑${g.type}父母关系"`)}</div>${['father','mother'].map(k=>byId(g[k])?personRow(byId(g[k]),(k==='father'?'父亲':'母亲')+' · '+lifespan(byId(g[k]))):button(icon('plus')+'添加'+(k==='father'?'父亲':'母亲'),'x-rel-start','x-add-row',`data-id="${p.id}" data-kind="${k}" data-group="${g.id}"`)).join('')}<div class="x-family-foot"><span>${esc(g.reason||'依据待补')}${g.source?' · '+esc(data.sources.find(s=>s.id===g.source)?.title||'来源'):''}</span>${button(data.preferredParents[p.id]===g.id||(!data.preferredParents[p.id]&&parents(p.id).id===g.id)?'当前树中显示':'在树中显示这组','x-parent-prefer','',`data-id="${p.id}" data-group="${g.id}"`)}</div></section>`).join('');const spouseBlocks=us.map(u=>{const spouse=byId(u.partners.find(id=>id!==p.id)),kids=allKids.filter(k=>groups(k.id).some(g=>[g.father,g.mother].includes(p.id)&&(!spouse||[g.father,g.mother].includes(spouse.id))));return `<section class="x-section"><div class="x-section-head"><h2>配偶与子女</h2>${button(icon('edit'),'x-union-edit','',`data-union="${u.id}" aria-label="编辑婚姻关系"`)}</div>${spouse?personRow(spouse,'配偶 · '+lifespan(spouse)):''}<div class="x-marriage-meta">${esc(u.status)} · ${esc(u.date||'日期待补')} · ${esc(u.place||'地点待补')}</div><div class="x-children"><label>子女 ${kids.length}</label>${kids.map(k=>personRow(k,lifespan(k)+' · '+(groups(k.id).find(g=>g.father===p.id||g.mother===p.id)?.type||''))).join('')}${button(icon('plus')+'添加子女','x-rel-start','x-add-row',`data-id="${p.id}" data-kind="child" data-union="${u.id}"`)}</div></section>`}).join('');const singleKids=allKids.filter(k=>!us.some(u=>groups(k.id).some(g=>u.partners.every(id=>[g.father,g.mother].includes(id)))));return `<div class="x-family-heading"><h2>父母与兄弟姐妹</h2>${button(icon('plus')+'另一组父母','x-parent-add','',`data-id="${p.id}"`)}</div>${parentBlocks||`<section class="x-section">${button(icon('plus')+'添加父母','x-parent-add','x-add-row',`data-id="${p.id}"`)}</section>`}${gs.length?`<section class="x-section"><div class="x-section-head"><h2>兄弟姐妹</h2></div>${data.people.filter(q=>q.id!==p.id&&groups(q.id).some(a=>gs.some(b=>(a.father&&a.father===b.father)||(a.mother&&a.mother===b.mother)))).map(q=>personRow(q)).join('')||'<p class="x-paragraph">暂无已录入的兄弟姐妹。</p>'}</section>`:''}<div class="x-family-heading"><h2>配偶与子女</h2>${button(icon('plus')+'添加配偶','x-rel-start','',`data-id="${p.id}" data-kind="spouse"`)}</div>${spouseBlocks}${singleKids.length?`<section class="x-section"><h2>另一位家长待补的子女</h2>${singleKids.map(k=>personRow(k)).join('')}</section>`:''}${!us.length?`<section class="x-section">${button(icon('plus')+'添加子女','x-rel-start','x-add-row',`data-id="${p.id}" data-kind="child"`)}</section>`:''}<p class="x-muted">亲生、收养、过继及继亲关系分别保存；不会覆盖原有父母。</p>`}
let relationDraft=null;
function relationStart(id,kind,group='',union=''){relationDraft={id,kind,group,union};const p=byId(id);modal('为'+esc(p.name)+'添加'+({father:'父亲',mother:'母亲',spouse:'配偶',child:'子女'}[kind]),`<p class="modal-description">先查找已有档案，避免重复创建人物。</p><div class="field"><label for="x-rel-query">姓名、原文名或人物编号</label><input id="x-rel-query" placeholder="输入姓名或 JX 编号" autocomplete="off"></div><div id="x-rel-results">${relationResults('')}</div>`,button(icon('plus')+'创建新人物','x-person-create','btn btn-primary'))}
function relationResults(q){const d=relationDraft;if(!d)return '';const list=data.people.filter(p=>p.id!==d.id&&(!q||norm(p.name+pID(p)+(data.china[p.id]?.originalName||'')).includes(norm(q)))).slice(0,12);return `<div class="x-select-list">${list.map(p=>`<button data-action="x-rel-select" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${lifespan(p)} · ${pID(p)}</small></span>${icon('plus')}</button>`).join('')||'<p class="x-muted">未找到已有档案，可创建新人物。</p>'}</div>`}
function relConfirm(target){const d=relationDraft,p=byId(target);if(!d||!p)return;modal('确认家庭关系',`<form id="x-rel-form" data-target="${target}"><div class="x-notice">${esc(byId(d.id).name)} → ${esc({father:'父亲',mother:'母亲',spouse:'配偶',child:'子女'}[d.kind])} ${esc(p.name)}<br><small>${pID(p)} · 使用已有档案</small></div>${d.kind==='spouse'?'':`<div class="field"><label for="x-rel-type">亲子关系类型</label><select id="x-rel-type">${kinTypes.map(t=>`<option ${data.parentGroups.find(g=>g.id===d.group)?.type===t?'selected':''}>${t}</option>`).join('')}</select></div>`}<div class="field"><label for="x-rel-reason">关系依据 *</label><textarea id="x-rel-reason" required maxlength="500" placeholder="例如：谱页卷二第18页明确记载父子关系"></textarea></div><button type="submit" class="btn btn-primary x-full">确认关联已有人物</button></form>`)}
function applyRelation(d,target,type,reason){const owner=byId(d.id),p=byId(target);if(!owner||!p||p.id===owner.id)throw Error('不能将人物与自己关联');if(d.kind==='spouse'){if(partners(owner.id).some(u=>u.partners.includes(p.id)))throw Error('这组配偶关系已存在');if(ancestorOf(owner.id,p.id)||ancestorOf(p.id,owner.id))throw Error('当前档案中双方存在祖先与后代关系，请先核对');data.unions.push({id:uid('u'),partners:[owner.id,p.id],status:'婚姻',date:'',place:'',reason});if(!owner.spouse)owner.spouse=p.id;if(!p.spouse)p.spouse=owner.id;return}
 const child=d.kind==='child'?p.id:owner.id,parent=d.kind==='child'?owner.id:p.id;validateParentEdge(child,parent);let g=data.parentGroups.find(x=>x.id===d.group&&x.type===type);if(d.kind==='child'){const spouse=byId(data.unions.find(u=>u.id===d.union)?.partners.find(id=>id!==owner.id));const father=owner.sex==='M'?owner.id:spouse?.id||'',mother=owner.sex==='F'?owner.id:spouse?.id||'';if(groups(child).some(g=>g.father===father&&g.mother===mother&&g.type===type))throw Error('这组亲子关系已存在');g={id:uid('pg'),child,father,mother,type,reason};data.parentGroups.push(g)}else{if(!g){g=groups(child).find(g=>g.type===type&&!g[d.kind]);if(!g){g={id:uid('pg'),child,father:'',mother:'',type,reason};data.parentGroups.push(g)}}if(g[d.kind]&&g[d.kind]!==p.id)throw Error('这组关系已有人物，请编辑该组父母或创建另一组');const other=g[d.kind==='father'?'mother':'father'];if(other===p.id)throw Error('同一人物不能同时占据这组父母的两个位置');g[d.kind]=p.id;g.reason=reason}syncParents(child)}
function personForm(id){corePersonForm(id)}
function corePersonForm(id){const p=id?byId(id):null;modal(p?'编辑人物资料':'创建人物档案',`<form id="x-person-form" data-id="${id||''}"><div class="form-grid">${[['name','姓名 *',p?.name||''],['birth','出生年份',p?.birth||''],['death','逝世年份',/^\d+$/.test(p?.death||'')?p.death:''],['place','出生地点',p?.place||'']].map(([n,t,v])=>`<div class="field ${n==='name'||n==='place'?'full':''}"><label for="x-p-${n}">${t}</label><input id="x-p-${n}" name="${n}" value="${esc(v)}" ${n==='name'?'required maxlength="40"':n==='birth'||n==='death'?'inputmode="numeric" pattern="[0-9]{0,4}" maxlength="4"':'maxlength="100"'}></div>`).join('')}<div class="field"><label for="x-p-sex">性别</label><select id="x-p-sex" name="sex"><option value="M">男</option><option value="F" ${(p?.sex==='F'||(!p&&relationDraft?.kind==='mother'))?'selected':''}>女</option></select></div><div class="field"><label for="x-p-living">生存状态</label><select id="x-p-living" name="life"><option value="living" ${!p?.death?'selected':''}>在世，受限可见</option><option value="deceased" ${p?.death?'selected':''}>已故</option></select></div>${!p&&relationDraft?.kind!=='spouse'?`<div class="field full"><label for="x-new-rel-type">亲子关系类型</label><select id="x-new-rel-type">${kinTypes.map(t=>`<option ${data.parentGroups.find(g=>g.id===relationDraft?.group)?.type===t?'selected':''}>${t}</option>`).join('')}</select></div>`:''}<div class="field full"><label for="x-p-bio">生平简述</label><textarea id="x-p-bio" name="bio" maxlength="1500">${esc(p?.bio||'')}</textarea></div><div class="field full"><label for="x-p-reason">${p?'修改依据':'录入及关系依据'} *</label><textarea id="x-p-reason" name="reason" required maxlength="500"></textarea></div></div>${p?'':'<div id="x-name-matches"></div><label class="check-row"><input type="checkbox" id="x-create-separate">若存在同名档案，我已核对，仍需创建独立人物。</label>'}<button class="btn btn-primary x-full" type="submit">${p?'保存修改':'创建并关联人物'}</button></form>`)}
function personOptions(selected='',blank='未记录'){return `<option value="">${blank}</option>`+data.people.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.name)} · ${pID(p)}</option>`).join('')}
function parentGroupForm(id,groupId){const g=data.parentGroups.find(g=>g.id===groupId);modal(g?'编辑父母关系':'添加另一组父母',`<form id="x-parent-form" data-person="${id}" data-group="${groupId||''}"><p class="modal-description">为${esc(byId(id).name)}保留独立的父母关系组。过继、收养不会删除亲生父母。</p><div class="field"><label for="x-pg-type">关系类型</label><select id="x-pg-type">${kinTypes.map(t=>`<option ${g?.type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="x-pg-father">父亲</label><select id="x-pg-father">${personOptions(g?.father)}</select></div><div class="field"><label for="x-pg-mother">母亲</label><select id="x-pg-mother">${personOptions(g?.mother)}</select></div><div class="field"><label for="x-pg-source">依据来源</label><select id="x-pg-source"><option value="">暂未关联，说明中补充</option>${data.sources.map(s=>`<option value="${s.id}" ${g?.source===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div class="field"><label for="x-pg-reason">关系依据与修改说明 *</label><textarea id="x-pg-reason" required maxlength="500">${esc(g?.reason||'')}</textarea></div><button class="btn btn-primary x-full" type="submit">保存这组父母关系</button>${g?button('解除这组关系，保留人物','x-parent-remove','x-danger-link',`data-group="${g.id}"`):''}</form>`)}
function unionForm(id){const u=data.unions.find(u=>u.id===id);if(!u)return;modal('编辑婚姻关系',`<form id="x-union-form" data-id="${id}"><div class="x-notice">${u.partners.map(id=>esc(byId(id)?.name)).join(' 与 ')}</div><div class="field"><label for="x-u-status">关系状态</label><select id="x-u-status">${['婚姻','再婚','离异','待考'].map(s=>`<option ${u.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label for="x-u-date">日期原文</label><input id="x-u-date" value="${esc(u.date)}" placeholder="保留农历、年号或约年原文"></div><div class="field"><label for="x-u-place">地点</label><input id="x-u-place" value="${esc(u.place)}"></div><div class="field"><label for="x-u-reason">修改依据 *</label><textarea id="x-u-reason" required>${esc(u.reason)}</textarea></div><button type="submit" class="btn btn-primary x-full">保存婚姻记录</button>${button('解除配偶关系，保留人物与子女','x-union-remove','x-danger-link',`data-id="${id}"`)}</form>`)}
function searchDialog(){state.searchText='';go('search')}
function searchView(){return `<div class="m-page">${coreHeader('搜索','当前家庭与样例资料',true)}<div class="x-search-top"><div class="m-memory-search">${icon('search')}<input id="x-global-query" aria-label="搜索姓名编号或资料" value="${esc(state.searchText)}" placeholder="姓名、繁简原文、编号、地点"></div><div class="x-fan-filters">${[['people','家族人物'],['records','历史资料']].map(([v,t])=>button(t,'x-search-mode',state.searchMode===v?'active':'',`data-mode="${v}"`)).join('')}</div></div><div class="x-search-results" id="x-search-results">${coreSearchResults()}</div></div>`}
function coreSearchResults(){const q=norm(state.searchText);if(state.searchMode==='records'){const list=catalog.filter(r=>!q||norm(r.title+r.name+r.style+r.origin+r.place).includes(q));return `<p class="x-muted">${list.length}条样例资料 · 当前未连接外部史料库</p>${list.map(r=>`<article class="x-record-result"><img src="${r.image}" alt="${esc(r.title)}"><div><span class="x-eyebrow">${esc(r.type)} · ${r.year}</span><h3>${esc(r.title)}</h3><p>${esc(r.name)} · ${esc(r.birth||'生年未记')} · ${esc(r.origin)}</p><small>父：${esc(r.father||'未记')}　母：${esc(r.mother||'未记')}</small><button data-action="x-record-target" data-record="${r.id}">核对并关联人物 ${icon('arrow-right')}</button></div></article>`).join('')}`}
const list=data.people.filter(p=>!q||norm(p.name+pID(p)+p.place+p.origin+JSON.stringify(data.china[p.id]||{})).includes(q));return `<p class="x-muted">${list.length}位人物 · 繁简姓名用于查找，原文分别保留</p>${list.map(p=>`<div class="x-search-person">${personRow(p)}${button(icon('tree'),'x-focus','m-icon-button',`data-id="${p.id}" aria-label="以${esc(p.name)}为中心查看家族树"`)}</div>`).join('')||'<div class="x-notice">未找到匹配人物。</div>'}`}
function tasksView(){const tab=state.taskFilter,records=catalog.filter(r=>!data.recordDecisions[r.id]),dups=duplicateCandidates('p3');return `<div class="m-page">${coreHeader('研究待办','逐条核对，让家谱更可靠')}<div class="x-task-summary"><strong>${openTasks()}</strong><span>项待核对<br><small>资料提示是线索，需要人工确认</small></span>${icon('check')}</div><div class="x-fan-filters x-task-tabs">${[['all','全部'],['records','资料提示'],['duplicates','可能重复'],['china','族谱校勘']].map(([v,t])=>button(t,'x-task-filter',tab===v?'active':'',`data-filter="${v}"`)).join('')}</div><div class="x-task-list">${['all','records'].includes(tab)?records.map(r=>`<article class="x-task-card"><span class="x-task-icon">${icon('file')}</span><div><span class="x-eyebrow">资料提示 · 林文海</span><h3>${esc(r.title)}</h3><p>${r.id==='r4'?'同名但父母、年代不同，需排除误接。':'核对名讳、父母与年代，再关联原文。'}</p><button data-action="x-record-compare" data-id="p3" data-record="${r.id}">核对资料 ${icon('arrow-right')}</button></div></article>`).join(''):''}${['all','duplicates'].includes(tab)?dups.map(p=>`<article class="x-task-card duplicate"><span class="x-task-icon">${icon('users')}</span><div><span class="x-eyebrow">可能重复 · 不自动合并</span><h3>两份“林文海”人物档案</h3><p>同名与出生年份接近，需要比较关系和来源。</p><button data-action="x-merge-compare" data-id="p3" data-other="${p.id}">比较人物 ${icon('arrow-right')}</button></div></article>`).join(''):''}${['all','china'].includes(tab)?`${!data.ocrDone?`<article class="x-task-card"><span class="x-task-icon">${icon('book')}</span><div><span class="x-eyebrow">AI谱页校勘</span><h3>一页老谱，等待确认</h3><p>保留谱页原图、繁体原文与核对结果。</p><button data-action="ocr-route">识读并校勘 ${icon('arrow-right')}</button></div></article>`:''}${!data.linked?`<article class="x-task-card"><span class="x-task-icon">${icon('pin')}</span><div><span class="x-eyebrow">闽台两谱联结</span><h3>南安与台南的家族线索</h3><p>核对父母、房支与原始记载，分别保留两谱。</p><a href="#roots">核对寻根线索 ${icon('arrow-right')}</a></div></article>`:''}`:''}${!openTasks()?'<div class="x-notice">本轮待办已核对完成。新的资料仍可继续补充。</div>':''}<a href="#clan" class="x-wide-link">${icon('branch')}管理字辈与房支 ${icon('chevron-right')}</a></div>${mobileDemo()}</div>`}
function recordTarget(rid){modal('选择要关联的人物',`<p class="modal-description">${esc(catalog.find(r=>r.id===rid).title)}。选择人物后逐项比较。</p><div class="x-select-list">${data.people.map(p=>`<button data-action="x-record-compare" data-record="${rid}" data-id="${p.id}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${lifespan(p)} · ${pID(p)}</small></span>${icon('chevron-right')}</button>`).join('')}</div>`)}
const compareFields=[['name','姓名'],['birth','出生年份'],['death','逝世年份'],['place','出生地点'],['origin','祖籍'],['style','字 / 号']];
function recordCompare(id,rid){const p=byId(id),r=catalog.find(r=>r.id===rid);if(!p||!r)return;const linked=data.sources.some(s=>s.recordId===rid&&s.person===id);modal('核对资料并关联',`<form id="x-record-form" data-person="${id}" data-record="${rid}"><div class="x-compare-head"><div><small>家族树人物</small><strong>${esc(p.name)}</strong><span>${pID(p)}</span></div><div><small>原始资料 · ${esc(r.year)}</small><strong>${esc(r.title)}</strong><span>虚构演示资料</span></div></div><img class="x-record-image" src="${r.image}" alt="${esc(r.title)}原图"><div class="x-quote">${esc(r.quote)}</div><div class="x-compare-parents"><span>当前父母：${[parents(id).father,parents(id).mother].map(x=>byId(x)?.name||'未记录').join(' / ')}</span><span>资料父母：${esc(r.father||'未记')} / ${esc(r.mother||'未记')}</span></div><p class="x-muted">默认保留现有字段。只有明确记载同一事实时才选用资料值；通信地点不能直接作为出生地。</p>${compareFields.filter(([k])=>r[k]&&k!=='death').map(([k,l])=>`<fieldset class="x-compare-field"><legend>${l}</legend><label><input type="radio" name="fact-${k}" value="current" checked><span><small>保留当前</small>${esc(p[k]||'未记录')}</span></label><label><input type="radio" name="fact-${k}" value="record"><span><small>使用资料值</small>${esc(r[k])}</span></label></fieldset>`).join('')}<label class="check-row"><input id="x-record-confirm" type="checkbox" required>已核对父母、年代和出处，确认资料属于此人。</label><div class="field"><label for="x-record-reason">关联及字段选择依据 *</label><textarea id="x-record-reason" required maxlength="600"></textarea></div><div class="x-form-actions"><button type="submit" class="btn btn-primary" ${linked?'disabled':''}>${linked?'已关联此条资料':'保存选择并关联'}</button>${button('不是此人','x-record-reject','btn',`data-record="${rid}" data-id="${id}"`)}</div></form>`,'',true)}
function duplicatesDialog(id){const list=duplicateCandidates(id);modal('可能重复的人物',`<p class="modal-description">按当前家庭中的姓名和已故状态筛选，仅为演示候选。不同谱本的关联与同树人物合并分别处理。</p>${list.map(p=>`<div class="x-source-card">${personRow(p)}<button class="x-wide-link" data-action="x-merge-compare" data-id="${id}" data-other="${p.id}">比较两份人物档案 ${icon('chevron-right')}</button></div>`).join('')||'<div class="x-notice">未发现当前规则下的候选重复人物。</div>'}`)}
function mergeCompare(id,other){const a=byId(id),b=byId(other);if(!a||!b)return;modal('比较重复人物',`<form id="x-merge-form" data-person="${id}" data-other="${other}"><div class="x-compare-head"><div><small>保留档案</small><strong>${esc(a.name)}</strong><span>${pID(a)}</span></div><div><small>待合并档案</small><strong>${esc(b.name)}</strong><span>${pID(b)}</span></div></div><div class="x-compare-parents"><span>父母：${[parents(id).father,parents(id).mother].map(x=>byId(x)?.name||'未记').join(' / ')}<br>${sourceCount(id)}条来源</span><span>父母：${[parents(other).father,parents(other).mother].map(x=>byId(x)?.name||'未记').join(' / ')}<br>${sourceCount(other)}条来源</span></div>${compareFields.map(([k,l])=>`<fieldset class="x-compare-field"><legend>${l}</legend><label><input type="radio" name="merge-${k}" value="current" checked><span>${esc(a[k]||'未记录')}</span></label><label><input type="radio" name="merge-${k}" value="other"><span>${esc(b[k]||'未记录')}</span></label></fieldset>`).join('')}<div class="x-notice">来源、记忆及关系转到保留档案；有差异的父母关系分别保留。被合并档案将归档，最近一次操作可在变更记录撤销。</div><label class="check-row"><input id="x-merge-confirm" type="checkbox" required>我已比较家庭关系及原始资料，确认两份档案为同一人。</label><div class="field"><label for="x-merge-reason">合并依据 *</label><textarea id="x-merge-reason" required maxlength="600"></textarea></div><div class="x-form-actions"><button type="submit" class="btn btn-primary">确认合并到${pID(a)}</button>${button('不是同一个人','x-duplicate-reject','btn',`data-id="${id}" data-other="${other}"`)}</div></form>`,'',true)}
function performMerge(id,other,choices){const a=byId(id),b=byId(other);if(!a||!b||id===other)throw Error('待合并档案不存在');if(!a.death||!b.death)throw Error('在世人物不在本次合并演示范围');if(ancestorOf(id,other)||ancestorOf(other,id)||partners(id).some(u=>u.partners.includes(other)))throw Error('双方存在直接祖先或配偶关系，需先核对关系，不能直接合并');for(const[k]of compareFields)if(choices['merge-'+k]==='other')a[k]=b[k]||'';data.sources.forEach(s=>{if(s.person===other)s.person=id});data.memories.forEach(m=>{if(m.person===other)m.person=id});data.notes.forEach(n=>{if(n.person===other)n.person=id});data.parentGroups.forEach(g=>{for(const k of ['child','father','mother'])if(g[k]===other)g[k]=id});data.parentGroups=data.parentGroups.filter((g,i,all)=>all.findIndex(q=>q.child===g.child&&q.father===g.father&&q.mother===g.mother&&q.type===g.type)===i);data.unions.forEach(u=>u.partners=u.partners.map(x=>x===other?id:x));data.unions=data.unions.filter((u,i,all)=>all.findIndex(q=>[...q.partners].sort().join(':')===[...u.partners].sort().join(':'))===i);data.people.forEach(p=>{for(const k of ['father','mother','spouse'])if(p[k]===other)p[k]=id});data.china[id]={...data.china[other],...data.china[id]};data.archivedPeople=[...(data.archivedPeople||[]),{...b,mergedInto:id}];data.people=data.people.filter(p=>p.id!==other);data.followed=[...new Set(data.followed.map(x=>x===other?id:x))];data.clan.branches.forEach(b=>{if(b.founder===other)b.founder=id});delete data.china[other];data.people.forEach(p=>syncParents(p.id));if(state.treeFocus===other)state.treeFocus=id}
function chinaForm(id,placeOnly=false){const c=data.china[id]||{},p=byId(id);const fields=placeOnly?[['placeOriginal','原文地名',c.placeOriginal||p.origin||''],['placeModern','现代地名候选',c.placeModern||''],['placeStatus','对应范围与核对状态',c.placeStatus||'待考']]:[['originalName','姓名原文',c.originalName||p.name],['genealogyName','谱名',c.genealogyName],['courtesy','字',c.courtesy],['artName','号',c.artName],['generation','世次',c.generation],['generationChar','字辈 / 派字',c.generationChar],['rank','房内排行',c.rank],['hall','堂号',c.hall],['dateOriginal','生辰原文（农历、干支、年号）',c.dateOriginal]];modal(placeOnly?'古今地名核对':'编辑中国族谱资料',`<form id="x-china-form" data-person="${id}"><p class="modal-description">${esc(p.name)} · 原文与整理字段分开保存，不自动换算农历或推定亲缘。</p><div class="form-grid">${fields.map(([k,l,v])=>`<div class="field ${['dateOriginal','placeOriginal','placeModern','placeStatus'].includes(k)?'full':''}"><label for="x-cn-${k}">${l}</label><input id="x-cn-${k}" name="${k}" value="${esc(v||'')}" maxlength="160"></div>`).join('')}${!placeOnly?`<div class="field full"><label for="x-cn-branch">房支</label><select id="x-cn-branch" name="branch"><option value="">待考</option>${data.clan.branches.map(b=>`<option value="${b.id}" ${c.branch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div>`:''}<div class="field full"><label for="x-cn-source">关联依据</label><select id="x-cn-source" name="source"><option value="">暂未关联</option>${data.sources.map(s=>`<option value="${s.id}" ${c.source===s.id?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div><div class="field full"><label for="x-cn-reason">整理或修改依据 *</label><textarea id="x-cn-reason" required name="reason" maxlength="600" placeholder="写明谱本卷页、家人口述或地名核对依据"></textarea></div></div><button type="submit" class="btn btn-primary x-full">保存原文与整理资料</button></form>`)}
function clanView(){const c=data.clan,poem=c.poem.trim().split(/[\s，、]+/).filter(Boolean);return `<div class="m-page">${coreHeader('字辈与房支','林氏家庭 · 中国族谱',true,button(icon('edit'),'x-clan-edit','m-icon-button','aria-label="编辑字辈与堂号"'))}<div class="x-clan-intro"><span class="x-eyebrow">族谱资料 · 虚构样例</span><h2>${esc(c.hall)}</h2><p>字辈、世次与房支分别记录，亲缘仍以关系及来源为依据。</p></div><section class="x-section"><div class="x-section-head"><h2>字辈序列</h2>${button('编辑','x-clan-edit','')}</div><div class="x-generation-poem">${poem.map((ch,i)=>`<div><strong>${esc(ch)}</strong><span>${Number(c.start)+i}世</span></div>`).join('')}</div>${poem.map((ch,i)=>{const ps=data.people.filter(p=>data.china[p.id]?.generationChar===ch);return `<div class="x-generation-row"><span>${esc(ch)}<small>${Number(c.start)+i}世</small></span><div>${ps.map(p=>`<a href="#person/${p.id}/details">${esc(p.name)}${p.relation==='待核重复档案'?' · 待核':''}</a>`).join('')||'<small>暂无已关联人物</small>'}</div></div>`}).join('')}</section><div class="x-family-heading"><h2>房支 ${c.branches.length}</h2>${button(icon('plus')+'新增房支','x-branch-edit','')}</div>${c.branches.map(b=>`<section class="x-section"><div class="x-section-head"><h2>${esc(b.name)}</h2>${button('编辑','x-branch-edit','',`data-id="${b.id}"`)}</div><p class="x-paragraph">始迁 / 房支起点：${esc(byId(b.founder)?.name||'待考')}<br>记载地点：${esc(b.place||'待核')}</p><div class="x-inline-links">${button('以此人查看家族树','x-focus','',`data-id="${b.founder}"`)}<span>${data.people.filter(p=>data.china[p.id]?.branch===b.id).length}位已标注人物</span></div></section>`).join('')}${mobileDemo()}</div>`}
function clanForm(){modal('编辑字辈与堂号',`<form id="x-clan-form"><div class="field"><label for="x-clan-hall">堂号原文</label><input id="x-clan-hall" value="${esc(data.clan.hall)}" required maxlength="100"></div><div class="field"><label for="x-clan-poem">字辈序列（空格分隔）</label><input id="x-clan-poem" value="${esc(data.clan.poem)}" required maxlength="100"></div><div class="field"><label for="x-clan-start">起始世次</label><input id="x-clan-start" type="number" min="1" max="200" value="${data.clan.start}" required></div><div class="field"><label for="x-clan-reason">谱本或修订依据 *</label><textarea id="x-clan-reason" required maxlength="500"></textarea></div><p class="x-muted">修改序列不会自动改名或变更人物世次。</p><button type="submit" class="btn btn-primary x-full">保存字辈资料</button></form>`)}
function branchForm(id){const b=data.clan.branches.find(b=>b.id===id);modal(b?'编辑房支':'新增房支',`<form id="x-branch-form" data-id="${id||''}"><div class="field"><label for="x-branch-name">房支名称 *</label><input id="x-branch-name" value="${esc(b?.name||'')}" required maxlength="60"></div><div class="field"><label for="x-branch-founder">起点人物 *</label><select id="x-branch-founder" required>${personOptions(b?.founder,'选择已录入人物')}</select></div><div class="field"><label for="x-branch-place">地点原文</label><input id="x-branch-place" value="${esc(b?.place||'')}" maxlength="100"></div><div class="field"><label for="x-branch-reason">设立或修改依据 *</label><textarea id="x-branch-reason" required maxlength="500"></textarea></div><button type="submit" class="btn btn-primary x-full">保存房支</button></form>`)}
function homeView(){return `<div class="m-page">${coreHeader('发现','家续 · 家庭记忆与中国族谱')}<div class="x-discover-welcome"><span class="x-eyebrow">从人物与原始资料开始</span><h2>接续家谱，也留下今天。</h2><p>查看家族关系，核对一页旧谱，听家人讲一段故事。</p></div><div class="x-discover-grid">${[['tree','家族树','tree'],['check','研究待办','tasks'],['branch','字辈与房支','clan'],['pin','闽台寻根','roots']].map(([i,t,r])=>`<a href="#${r}">${icon(i)}<strong>${t}</strong>${icon('chevron-right')}</a>`).join('')}</div><div class="x-family-heading"><h2>继续研究</h2><a href="#tasks">${openTasks()}项待办</a></div><button class="x-feature-record" data-action="x-record-compare" data-id="p3" data-record="r1"><img src="assets/genealogy.svg" alt="林氏家谱示例谱页"><span><small>林文海 · 资料提示</small><strong>核对谱页中的名讳与父母</strong><em>对照原文，再关联人物 ${icon('arrow-right')}</em></span></button><div class="x-family-heading"><h2>AI整理助手</h2><a href="#studio">打开助手</a></div><div class="x-discover-grid compact">${[['book','识读老谱','ocr-route'],['mic','口述访谈','interview-route'],['sparkles','问家事','x-chat-open'],['image','保存记忆','upload-memory']].map(([i,t,a])=>`<button data-action="${a}">${icon(i)}<strong>${t}</strong></button>`).join('')}</div><div class="x-family-heading"><h2>家庭记忆</h2><a href="#memories">查看全部</a></div><div class="m-body"><div class="memory-grid">${data.memories.slice(0,2).map(memoryCard).join('')}</div></div>${mobileDemo()}</div>`}
function rootsView(){return `<div class="m-page">${coreHeader('闽台寻根','跨谱联结 · 保留各自原文与版本',true)}<section class="x-roots-intro"><span class="x-eyebrow">南安 · 金门 · 台南</span><h2>沿着资料，寻找两地家脉。</h2><p>名讳、父母、世次与房支交叉核对，保留迁徙年代的不确定性。</p></section><div class="m-body"><section class="x-section"><div class="x-section-head"><h2>林文海的迁徙线索</h2><span class="x-pill amber">年份待考</span></div><div class="m-route-diagram">${[['南安','1924 · 谱页','s1'],['金门','约1948 · 口述','s3'],['台南','1962 · 家书','s2']].map(([n,t,id])=>`<button class="m-route-stop" data-action="source" data-id="${id}"><span>${icon('pin')}</span>${n}<small>${t}</small></button>`).join('')}</div><p class="x-muted">示意路线，不代表精确行程。通信地点与居住地点分别核对。</p></section><section class="x-section"><div class="x-section-head"><h2>两地谱本候选关联</h2><span class="x-pill ${data.linked?'':'amber'}">${data.linked?'已关联':'待核对'}</span></div><div class="x-crossbook"><div><span>闽南谱本</span><strong>林文海 · 字承远</strong><small>南安 · 林宗源之子</small></div>${icon('branch')}<div><span>台南家庭补记</span><strong>林文海 · 字承遠</strong><small>原籍南安 · 父宗源</small></div></div><button class="btn btn-primary x-full" data-action="compare">${data.linked?'查看或解除两谱关联':'核对名讳、父母与出处'}</button><p class="x-muted">关联后各谱本仍独立。不会把另一谱本的人物与整棵家族树直接合并。</p></section><section class="x-section"><div class="x-section-head"><h2>古今地名对照</h2>${button('核对','x-place-edit','',`data-id="p3"`)}</div><div class="x-fact-list"><div><label>原文</label><span>${esc(data.china.p3?.placeOriginal||'泉州南安')}</span></div><div><label>现代候选</label><span>${esc(data.china.p3?.placeModern||'福建省泉州市南安市')}</span></div><div><label>核对状态</label><span>${esc(data.china.p3?.placeStatus||'待考')}</span></div></div></section><section class="x-section"><div class="x-section-head"><h2>原文资料与研究笔记</h2>${button('补充','add-clue','')}</div>${data.sources.filter(s=>s.person==='p3').map(s=>`<button class="x-wide-link" data-action="source" data-id="${s.id}">${icon('file')}${esc(s.title)}${icon('chevron-right')}</button>`).join('')}${data.notes.filter(n=>n.person==='p3').map(n=>`<p class="x-paragraph">${esc(n.text)}</p>`).join('')}</section></div>${mobileDemo()}</div>`}
function mobileMeView(){return `<div class="m-page">${coreHeader('更多','林氏家庭空间',false,button(icon('users'),'invite','m-icon-button','aria-label="邀请家人加入"'))}<div class="m-body"><div class="m-account-hero">${avatar(byId('p0'))}<div><h2>${esc(byId('p0').name)}</h2><p>家庭管理员 · 本地体验</p></div></div><div class="m-account-stats"><div><strong>${data.people.length}</strong><span>位人物</span></div><div><strong>${data.sources.length}</strong><span>条来源</span></div><div><strong>${data.memories.length}</strong><span>段记忆</span></div></div><section class="x-section x-menu">${[['branch','字辈、世次与房支','x-clan-open'],['users','家庭成员与邀请','members'],['star','关注的人物','x-following'],['file','搜索历史资料','x-record-search'],['history','最近修改与撤销','x-all-changes'],['download','资料备份与导出','export'],['sparkles','AI整理助手','mobile-ocr']].map(([i,t,a])=>button(icon(i)+t+icon('chevron-right'),a,'x-wide-link')).join('')}</section><section class="x-section x-menu">${[['help','原型体验指引','guide'],['shield','隐私与演示说明','about'],['history','恢复初始演示','reset-dialog']].map(([i,t,a])=>button(icon(i)+t+icon('chevron-right'),a,'x-wide-link')).join('')}</section><p class="x-muted">原型数据保存在当前浏览器。真实账号、权限、史料检索及AI服务将在正式开发中接入。</p></div>${mobileDemo()}</div>`}
function guide(){modal('V3核心流程体验',`<p class="modal-description">人物、资料与谱本均为虚构样例。下面的关系编辑、字段选择、关联及撤销会保存在当前浏览器。</p><div class="m-howto">${[['01','祖先图 → 点人物 → 查看此人的树','tree'],['02','人物家庭 → 添加父母、配偶或子女','person/p3/family'],['03','研究待办 → 核对资料 → 选择字段并关联','tasks'],['04','重复人物 → 比较合并 → 变更记录撤销','person/p3/details'],['05','字辈与房支 → 编辑序列及房支人物','clan'],['06','闽台寻根 → 地名对照及两谱关联','roots']].map(([n,t,r])=>`<a href="#${r}"><span>${n}</span>${t}${icon('chevron-right')}</a>`).join('')}</div>`)}
function sourceDialog(id){const s=data.sources.find(s=>s.id===id);if(!s)return;modal('来源原文与关联',`<img class="x-record-image large" src="${s.image||'assets/genealogy.svg'}" alt="${esc(s.title)}原始示意资料"><span class="x-eyebrow">${esc(s.type)} · ${esc(s.year)} · 虚构资料</span><h3>${esc(s.title)}</h3><p class="x-paragraph">${esc(s.desc)}</p><div class="x-quote">${esc(s.quote)}</div><div class="x-fact-list"><div><label>关联人物</label><a href="#person/${s.person}/sources">${esc(byId(s.person)?.name||'待核')} · ${byId(s.person)?pID(byId(s.person)):''}</a></div><div><label>关联说明</label><span>${esc(s.attachReason||'家庭收集资料，仍可补充核对说明')}</span></div></div><p class="x-muted">来源关联与人物事实分别保存；字段采纳记录可在人物“变更”中查看。</p>`)}
function reasonDialog(title,action,attrs=''){modal(title,`<div class="field"><label for="x-decision-reason">判断依据 *</label><textarea id="x-decision-reason" required maxlength="600" placeholder="写明父母、年代、房支或原文中不一致的地方"></textarea></div>`,button('取消','close-modal','btn')+button('确认并保存判断',action,'btn btn-primary',attrs))}
function removeDialog(title,action,attrs){modal(title,`<p class="modal-description">只解除所选关系或来源关联，保留人物及其他资料。此次操作可在最近修改中撤销。</p><div class="field"><label for="x-remove-reason">解除依据 *</label><textarea id="x-remove-reason" required maxlength="600"></textarea></div>`,button('取消','close-modal','btn')+button('确认解除',action,'btn btn-primary',attrs))}
function coreClick(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(!a.startsWith('x-'))return;e.preventDefault();e.stopImmediatePropagation();
 if(a==='x-focus')coreFocus(id);
 else if(a==='x-person-open')go('person/'+id+'/details');
 else if(a==='x-family-open')go('person/'+id+'/family');
 else if(a==='x-tree-home')coreFocus('p0');
 else if(a==='x-centre'){state.zoom=1;render()}
 else if(a==='x-zoom-in'||a==='x-zoom-out')setTreeZoom(state.zoom+(a==='x-zoom-in'?.12:-.12));
 else if(a==='x-fan-filter'){state.fanMode=el.dataset.mode;render()}
 else if(a==='x-tree-history')modal('最近浏览人物',`<div class="x-select-list">${state.treeRecent.filter(byId).map(id=>`<button data-action="x-focus" data-id="${id}">${avatar(byId(id))}<span><strong>${esc(byId(id).name)}</strong><small>${pID(byId(id))}</small></span>${icon('tree')}</button>`).join('')}</div>`);
 else if(a==='x-branches')modal('按房支查看',`<p class="modal-description">切换到房支起点人物，父系与母系继续共同显示。</p><div class="x-select-list">${data.clan.branches.map(b=>`<button data-action="x-focus" data-id="${b.founder}">${icon('branch')}<span><strong>${esc(b.name)}</strong><small>${esc(byId(b.founder)?.name||'待考')} · ${esc(b.place)}</small></span>${icon('chevron-right')}</button>`).join('')}</div><a class="x-wide-link" href="#clan">管理字辈与房支 ${icon('chevron-right')}</a>`);
 else if(a==='x-parent-choice')modal('选择树中显示的父母',`<div class="x-select-list">${groups(id).map(g=>`<button data-action="x-parent-prefer" data-id="${id}" data-group="${g.id}"><span><strong>${esc(g.type)}父母</strong><small>${[g.father,g.mother].map(x=>byId(x)?.name||'未录入').join(' / ')}</small></span>${icon('tree')}</button>`).join('')}</div>`);
 else if(a==='x-parent-prefer'){data.preferredParents[id]=el.dataset.group;syncParents(id);save();closeModal();render();toast('已切换树中显示的父母，其他关系仍保留')}
 else if(a==='x-desc-toggle'){const i=state.descClosed.indexOf(id);if(i<0)state.descClosed.push(id);else state.descClosed.splice(i,1);render()}
 else if(a==='x-relationship')showRelationship(id);
 else if(a==='x-rel-start')relationStart(id,el.dataset.kind,el.dataset.group,el.dataset.union);
 else if(a==='x-rel-select')relConfirm(id);
 else if(a==='x-person-create')corePersonForm();
 else if(a==='x-parent-add')parentGroupForm(id);
 else if(a==='x-parent-edit'){const g=data.parentGroups.find(g=>g.id===el.dataset.group);parentGroupForm(g.child,g.id)}
 else if(a==='x-union-edit')unionForm(el.dataset.union);
 else if(a==='x-parent-remove')removeDialog('解除这组父母关系','x-remove-parent-confirm',`data-group="${el.dataset.group}"`);
 else if(a==='x-union-remove')removeDialog('解除配偶关系','x-remove-union-confirm',`data-id="${id}"`);
 else if(a==='x-source-unlink')removeDialog('解除来源关联','x-remove-source-confirm',`data-id="${id}"`);
 else if(a.startsWith('x-remove-')&&a.endsWith('-confirm')){const reason=$('#x-remove-reason').value.trim();if(!reason){toast('请填写解除依据');return}if(a==='x-remove-parent-confirm'){const g=data.parentGroups.find(g=>g.id===el.dataset.group);commitCore(g.child,'解除'+g.type+'父母关系',reason,()=>{data.parentGroups=data.parentGroups.filter(x=>x.id!==g.id);delete data.preferredParents[g.child];syncParents(g.child)})}else if(a==='x-remove-union-confirm'){const u=data.unions.find(u=>u.id===id);commitCore(u.partners[0],'解除配偶关系',reason,()=>{data.unions=data.unions.filter(x=>x.id!==id);u.partners.forEach(pid=>{const p=byId(pid);if(u.partners.includes(p.spouse))p.spouse=partners(pid)[0]?.partners.find(x=>x!==pid)||''})})}else{const s=data.sources.find(s=>s.id===id);commitCore(s.person,'解除来源关联',reason,()=>data.sources=data.sources.filter(x=>x.id!==id))}closeModal();render();toast('已解除所选关联，保留修改记录')}
 else if(a==='x-person-tools')modal('人物工具',`<div class="x-menu">${button(icon('edit')+'编辑重要资料','edit-person','x-wide-link',`data-id="${id}"`)}${button(icon('book')+'中国族谱资料','x-china-edit','x-wide-link',`data-id="${id}"`)}${button(icon('users')+'可能重复人物','x-duplicates','x-wide-link',`data-id="${id}"`)}${button(icon('branch')+'与我的关系','x-relationship','x-wide-link',`data-id="${id}"`)}<a class="x-wide-link" href="#person/${id}/changes">${icon('history')}修改记录与撤销</a></div>`);
 else if(a==='x-task-filter'){state.taskFilter=el.dataset.filter;render()}
 else if(a==='x-search-mode'){state.searchMode=el.dataset.mode;render()}
 else if(a==='x-record-search'){state.searchMode='records';state.searchText='';go('search')}
 else if(a==='x-source-add'){modal('添加来源',`<div class="x-menu">${button(icon('search')+'从样例资料检索并核对','x-record-search','x-wide-link')}${button(icon('plus')+'手动登记家庭资料','add-source','x-wide-link',`data-id="${id}"`)}</div>`)}
 else if(a==='x-record-target')recordTarget(el.dataset.record);
 else if(a==='x-record-compare')recordCompare(id,el.dataset.record);
 else if(a==='x-record-reject')reasonDialog('记录“不是此人”的依据','x-record-reject-confirm',`data-record="${el.dataset.record}" data-id="${id}"`);
 else if(a==='x-record-reject-confirm'){const reason=$('#x-decision-reason').value.trim();if(!reason){toast('请写明判断依据');return}commitCore(id,'排除一条资料提示',reason,()=>data.recordDecisions[el.dataset.record]={status:'not-match',person:id,reason});closeModal();render();toast('已记录排除依据，此条提示从待办移除')}
 else if(a==='x-duplicates')duplicatesDialog(id);
 else if(a==='x-merge-compare')mergeCompare(id,el.dataset.other);
 else if(a==='x-duplicate-reject')reasonDialog('记录“不是同一个人”的依据','x-duplicate-reject-confirm',`data-id="${id}" data-other="${el.dataset.other}"`);
 else if(a==='x-duplicate-reject-confirm'){const reason=$('#x-decision-reason').value.trim();if(!reason){toast('请写明判断依据');return}commitCore(id,'排除重复人物候选',reason,()=>data.duplicateDecisions[[id,el.dataset.other].sort().join(':')]={reason});closeModal();render();toast('已保留两份独立档案并记录排除依据')}
 else if(a==='x-undo-dialog'){const r=data.revisions[0];if(!r)return;modal('撤销最近修改',`<h3>${esc(r.title)}</h3><p class="x-paragraph">${esc(r.reason)}</p><p class="modal-description">恢复该操作前的人物、关系和来源。仅支持当前最新且没有后续资料变化的一次修改。</p>`,button('取消','close-modal','btn')+button('确认撤销最近修改','x-undo-confirm','btn btn-primary'))}
 else if(a==='x-undo-confirm')undoCore();
 else if(a==='x-china-edit')chinaForm(id);
 else if(a==='x-place-edit')chinaForm(id,true);
 else if(a==='x-clan-open')go('clan');
 else if(a==='x-clan-edit')clanForm();
 else if(a==='x-branch-edit')branchForm(id);
 else if(a==='x-chat-open'){state.studioMode='chat';go('studio')}
 else if(a==='x-following')modal('关注的人物',data.followed.length?data.followed.filter(byId).map(id=>personRow(byId(id))).join(''):'<p class="x-muted">在人物资料中点击星标，可将人物加入关注。</p>');
 else if(a==='x-all-changes')modal('最近修改',data.revisions.map((r,i)=>`<article class="x-revision"><strong>${esc(r.title)}</strong><p>${esc(r.reason)}</p><small>${esc(r.time)}</small>${i===0?button('查看并撤销最近修改','x-undo-dialog',''):''}</article>`).join('')||'<p class="x-muted">暂无本次体验的修改。</p>');
}
document.addEventListener('click',coreClick,true);
document.addEventListener('input',e=>{if(e.target.id==='x-rel-query')$('#x-rel-results').innerHTML=relationResults(e.target.value);if(e.target.id==='x-global-query'){state.searchText=e.target.value;$('#x-search-results').innerHTML=coreSearchResults()}if(e.target.id==='x-p-name'&&!$('#x-person-form').dataset.id){const list=data.people.filter(p=>norm(p.name)===norm(e.target.value));$('#x-name-matches').innerHTML=list.length?'<div class="x-notice">已有同名档案：'+list.map(p=>esc(p.name)+' '+pID(p)).join('、')+'。请先核对再决定是否独立创建。</div>':''}});
document.addEventListener('change',e=>{if(e.target.id==='x-generations'){state.generations=Number(e.target.value);state.zoom=1;render()}});
document.addEventListener('submit',e=>{const f=e.target;if(!f.id.startsWith('x-'))return;e.preventDefault();e.stopImmediatePropagation();try{
 if(f.id==='x-rel-form'){const d={...relationDraft},target=f.dataset.target,type=$('#x-rel-type')?.value||'亲生',reason=$('#x-rel-reason').value.trim();if(!reason)return;const before=corePayload();try{commitCore(d.id,'关联家庭成员',reason,()=>applyRelation(d,target,type,reason))}catch(err){Object.assign(data,before);throw err}closeModal();go('person/'+d.id+'/family');toast('已关联已有档案并保存关系依据')}
 else if(f.id==='x-person-form'){const v=Object.fromEntries(new FormData(f)),id=f.dataset.id;v.name=v.name.trim();v.reason=v.reason.trim();if(!v.name||!v.reason)throw Error('请填写姓名和依据');if(v.birth&&v.death&&Number(v.death)<Number(v.birth))throw Error('逝世年份不能早于出生年份');if(v.life==='living'&&v.death)throw Error('在世状态与逝世年份不一致，请核对');const payload={name:v.name,sex:v.sex,birth:v.birth.trim(),death:v.life==='living'?'':v.death.trim()||'未知',place:v.place.trim(),bio:v.bio.trim()};if(id){commitCore(id,'修改人物重要资料',v.reason,()=>Object.assign(byId(id),payload));closeModal();render();toast('人物资料和修改依据已保存')}else{if(data.people.some(p=>norm(p.name)===norm(v.name))&&!$('#x-create-separate').checked)throw Error('发现同名档案，请先核对并勾选独立创建确认');const d={...(relationDraft||{id:state.treeFocus||'p0',kind:'child'})},newId=uid('p'),before=corePayload();try{commitCore(d.id,'创建并关联人物 '+v.name,v.reason,()=>{data.people.push({id:newId,...payload,relation:'家族成员'});applyRelation(d,newId,$('#x-new-rel-type')?.value||'亲生',v.reason)})}catch(err){Object.assign(data,before);throw err}closeModal();go('person/'+newId+'/details');toast('已创建档案并保存家庭关系')}}
 else if(f.id==='x-parent-form'){const id=f.dataset.person,groupId=f.dataset.group,father=$('#x-pg-father').value,mother=$('#x-pg-mother').value,type=$('#x-pg-type').value,reason=$('#x-pg-reason').value.trim();if(!father&&!mother)throw Error('至少选择一位父亲或母亲');if(father&&father===mother)throw Error('同一人物不能同时占据父母两个位置');for(const parent of [father,mother].filter(Boolean))validateParentEdge(id,parent);if(groups(id).some(g=>g.id!==groupId&&g.father===father&&g.mother===mother&&g.type===type))throw Error('相同父母关系已存在');commitCore(id,groupId?'修改父母关系':'添加'+type+'父母',reason,()=>{const g={id:groupId||uid('pg'),child:id,father,mother,type,reason,source:$('#x-pg-source').value};const i=data.parentGroups.findIndex(g=>g.id===groupId);if(i<0)data.parentGroups.push(g);else data.parentGroups[i]=g;syncParents(id)});closeModal();go('person/'+id+'/family');toast('已保存独立父母关系，原有其他关系保留')}
 else if(f.id==='x-union-form'){const u=data.unions.find(u=>u.id===f.dataset.id),reason=$('#x-u-reason').value.trim();commitCore(u.partners[0],'修改婚姻记录',reason,()=>Object.assign(u,{status:$('#x-u-status').value,date:$('#x-u-date').value.trim(),place:$('#x-u-place').value.trim(),reason}));closeModal();render();toast('婚姻记录已保存')}
 else if(f.id==='x-record-form'){const id=f.dataset.person,r=catalog.find(r=>r.id===f.dataset.record),v=Object.fromEntries(new FormData(f)),reason=$('#x-record-reason').value.trim();if(!$('#x-record-confirm').checked||!reason)throw Error('请核对确认项并填写依据');if(data.sources.some(s=>s.person===id&&s.recordId===r.id))throw Error('此条资料已关联，不重复创建');commitCore(id,'核对并关联资料《'+r.title+'》',reason,()=>{const p=byId(id);for(const [k]of compareFields)if(v['fact-'+k]==='record')p[k]=r[k];data.sources.push({id:uid('s'),person:id,recordId:r.id,title:r.title,type:r.type,year:r.year,quote:r.quote,image:r.image,desc:'家庭资料检索样例，经人工比较关联',attachReason:reason});data.recordDecisions[r.id]={status:'attached',person:id,reason}});closeModal();go('person/'+id+'/sources');toast('来源已关联，字段按你的选择保存')}
 else if(f.id==='x-merge-form'){const id=f.dataset.person,other=f.dataset.other,reason=$('#x-merge-reason').value.trim(),v=Object.fromEntries(new FormData(f));if(!$('#x-merge-confirm').checked||!reason)throw Error('请确认是同一人并填写合并依据');const before=corePayload();try{commitCore(id,'合并重复人物档案',reason,()=>performMerge(id,other,v))}catch(err){Object.assign(data,before);throw err}closeModal();go('person/'+id+'/changes');toast('已合并人物并转移关系、记忆和来源，可撤销最近修改')}
 else if(f.id==='x-china-form'){const id=f.dataset.person,v=Object.fromEntries(new FormData(f)),reason=v.reason.trim();delete v.reason;commitCore(id,'整理中国族谱资料',reason,()=>{data.china[id]={...data.china[id],...v}});closeModal();render();toast('已保存原文、整理字段及依据')}
 else if(f.id==='x-clan-form'){const reason=$('#x-clan-reason').value.trim(),poem=$('#x-clan-poem').value.trim();if(!poem)throw Error('请填写字辈序列');commitCore('clan','修改字辈与堂号',reason,()=>Object.assign(data.clan,{hall:$('#x-clan-hall').value.trim(),poem,start:Number($('#x-clan-start').value)}));closeModal();render();toast('字辈资料已保存，人物姓名及世次未自动改变')}
 else if(f.id==='x-branch-form'){const id=f.dataset.id||uid('b'),reason=$('#x-branch-reason').value.trim();commitCore('clan',f.dataset.id?'修改房支':'新增房支',reason,()=>{const b={id,name:$('#x-branch-name').value.trim(),founder:$('#x-branch-founder').value,place:$('#x-branch-place').value.trim(),reason};const i=data.clan.branches.findIndex(b=>b.id===id);if(i<0)data.clan.branches.push(b);else data.clan.branches[i]=b});closeModal();render();toast('房支资料已保存')}
 }catch(err){toast(err.message||'请核对必填资料')}} ,true);
// Override generic creation/reset flows so every person uses the same relationship store.
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='add-person'){e.preventDefault();e.stopImmediatePropagation();relationStart(state.route==='person'?state.person:state.treeFocus||'p0','child')}if(el.dataset.action==='reset-demo'){e.preventDefault();e.stopImmediatePropagation();data={people:structuredClone(peopleSeed),memories:structuredClone(memorySeed),sources:structuredClone(sourceSeed),favorites:[],followed:[],activities:[],notes:[],ocrDone:false,linked:false};initCore();state.ocrStage=1;state.chat=[];state.interviewStep=0;state.treeFocus='p0';state.generations=3;state.zoom=1;state.treeView='portrait';closeModal();go('tree');toast('已恢复V3虚构演示资料')}} ,true);

